  const sunset = angleTime(horizon, noon, lat, decl, true);
  let fajr = angleTime(m.fajr, noon, lat, decl);
  const asrAngle = -arccot((asrHanafi ? 2 : 1) + tan(Math.abs(lat - decl)));
  const asr = angleTime(asrAngle, noon, lat, decl, true);
  let isha = m.ishaMin ? sunset + m.ishaMin / 60 : angleTime(m.isha, noon, lat, decl, true);

  let note = null;
  if (!Number.isNaN(sunrise) && !Number.isNaN(sunset)) {
    const night = fix(sunrise - sunset, 24);
    if (Number.isNaN(fajr)) { fajr = sunrise - night / 7; note = NOTE; }
    else if (sunrise - fajr > (night * m.fajr) / 60) { fajr = sunrise - (night * m.fajr) / 60; note = NOTE; }
    if (!m.ishaMin) {
      if (Number.isNaN(isha)) { isha = sunset + night / 7; note = NOTE; }
      else if (isha - sunset > (night * m.isha) / 60) { isha = sunset + (night * m.isha) / 60; note = NOTE; }
    }
  }
  const shift = offset - lon / 15;
  const raw = { fajr, sunrise, dhuhr: noon + 1 / 60, asr, maghrib: sunset, isha };
  const ms = {}, text = {};
  for (const [k, v] of Object.entries(raw)) {
    if (Number.isNaN(v)) { ms[k] = null; text[k] = '—'; continue; }
    const mins = Math.round((v + shift) * 60);                      // минуты от местной полуночи
    ms[k] = Date.UTC(y, mo - 1, d) + mins * 60000 - offset * 3600000;
    const wrapped = ((mins % 1440) + 1440) % 1440;
    text[k] = `${String(Math.floor(wrapped / 60)).padStart(2, '0')}:${String(wrapped % 60).padStart(2, '0')}`;
  }
  return { ms, text, note, offset };
}

/** Начало последней трети ночи: Магриб + 2/3 ночи (до Фаджра следующего дня) */
function tahajjudMs(today, tomorrow) {
  if (!today.ms.maghrib || !tomorrow.ms.fajr) return null;
  return today.ms.maghrib + ((tomorrow.ms.fajr - today.ms.maghrib) * 2) / 3;
}

/* ───────── Хиджра (табличный Кувейтский алгоритм) ───────── */
function toHijri({ y, m, d }) {
  const jd = Math.floor(Date.UTC(y, m - 1, d) / 86400000) + 2440588;     // юлианский день на полдень (целое)
  let l = jd - 1948440 + 10632;
  const n = Math.floor((l - 1) / 10631);
  l = l - 10631 * n + 354;
  const j = Math.floor((10985 - l) / 5316) * Math.floor((50 * l) / 17719) + Math.floor(l / 5670) * Math.floor((43 * l) / 15238);
  l = l - Math.floor((30 - j) / 15) * Math.floor((17719 * j) / 50) - Math.floor(j / 16) * Math.floor((15238 * j) / 43) + 29;
  const month = Math.floor((24 * l) / 709);
  const day = l - Math.floor((709 * month) / 24);
  const year = 30 * n + j - 30;
  return { year, month, day, text: `${day} ${HIJRI_MONTHS[month - 1]} ${year}` };
}

/* ───────── Кибла ───────── */
function qiblaBearing(lat, lon) {
  const p1 = lat * D2R, p2 = KAABA.lat * D2R, dl = (KAABA.lon - lon) * D2R;
  const y = Math.sin(dl) * Math.cos(p2);
  const x = Math.cos(p1) * Math.sin(p2) - Math.sin(p1) * Math.cos(p2) * Math.cos(dl);
  return (Math.atan2(y, x) * R2D + 360) % 360;
}
function distanceToKaabaKm(lat, lon) {
  const R = 6371, dLat = (KAABA.lat - lat) * D2R, dLon = (KAABA.lon - lon) * D2R;
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(lat * D2R) * Math.cos(KAABA.lat * D2R) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(a));
}

return { tzOffsetHours, deviceTz, todayIn, shiftDate, computeDay, tahajjudMs, toHijri, qiblaBearing, distanceToKaabaKm };
})();

/* ── core/notify.js ── */
const __m_core_notify = (() => {
// Напоминания о намазе и «умный будильник» (Фаджр / Тахаджуд / Сухур).
// Веб-ограничение: уведомления срабатывают, пока приложение открыто (вкладка или установленное PWA).
const { getSettings } = __m_core_store;
const { computeDay, todayIn, shiftDate, tahajjudMs } = __m_core_prayer;
const { OBLIGATORY } = __m_core_meta;
const { toast } = __m_core_ui;

let timers = [];
const supported = () => typeof Notification !== 'undefined';
const notificationsSupported = supported;
const notificationState = () => (supported() ? Notification.permission : 'unsupported');

async function askPermission() {
  if (!supported()) { toast('Этот браузер не поддерживает уведомления'); return false; }
  if (Notification.permission === 'granted') return true;
  if (Notification.permission === 'denied') { toast('Уведомления запрещены в настройках браузера'); return false; }
  try { return (await Notification.requestPermission()) === 'granted'; } catch { return false; }
}

function fire(title, body) {
  try { new Notification(title, { body, icon: '/static/icons/icon-192.png', tag: 'svet-' + title }); } catch { /* не удалось показать */ }
}

function rescheduleNotifications() {
  timers.forEach(clearTimeout);
  timers = [];
  if (!supported() || Notification.permission !== 'granted') return;
  const s = getSettings(), loc = s.loc, now = Date.now();
  const base = todayIn(loc.tz);
  const days = [0, 1, 2].map((i) => computeDay(shiftDate(base, i), loc, s.method, s.asrHanafi));
  const ev = [];
  for (let i = 0; i < 2; i++) {
    const d = days[i];
    if (s.notify) for (const p of OBLIGATORY) if (d.ms[p.key]) ev.push([d.ms[p.key], `Время намаза: ${p.ru}`, loc.name]);
    if (s.alarm.fajr && d.ms.fajr) ev.push([d.ms.fajr, 'Время Фаджра', 'Наступило время утреннего намаза']);
    if (s.alarm.suhur && d.ms.fajr) ev.push([d.ms.fajr - s.alarm.suhurMin * 60000, 'Сухур', `Осталось ${s.alarm.suhurMin} минут до Фаджра — время сухура`]);
    if (s.alarm.tahajjud) {
      const t = tahajjudMs(d, days[i + 1]);
      if (t) ev.push([t, 'Тахаджуд', 'Наступила последняя треть ночи — время тахаджуда']);
    }
  }
  for (const [ms, title, body] of ev) {
    const wait = ms - now;
    if (wait > 0 && wait < 2 ** 31 - 1) timers.push(setTimeout(() => fire(title, body), wait));
  }
  // раз в сутки пересчитываем расписание заново
  const next = new Date(); next.setHours(24, 1, 0, 0);
  timers.push(setTimeout(rescheduleNotifications, next - now));
}

return { notificationsSupported, notificationState, askPermission, rescheduleNotifications };
})();

/* ── core/remote.js ── */
const __m_core_remote = (() => {
// Внешние источники, как в исходном приложении: таджвид (alquran.cloud) и тафсир Ибн Касира (spa5k/tafsir_api).
const { TAJWEED_CLASS } = __m_core_meta;
const { normAr } = __m_core_data;
const { esc } = __m_core_ui;

async function getJSON(url, ms) {
  const ctl = new AbortController();
  const t = setTimeout(() => ctl.abort(), ms);
  try {
    const r = await fetch(url, { signal: ctl.signal });
    if (!r.ok) throw new Error('HTTP ' + r.status);
    return await r.json();
  } finally { clearTimeout(t); }
}

/* ───────── Таджвид ───────── */
const HEAVY = new Set(['خ', 'ص', 'ض', 'ط', 'ظ', 'غ', 'ق']);
const DIACRITIC = /[ؐ-ًؚ-ٰٟۖ-ۭ]/;
const SILENT_CIRCLE = /[۟۠]/g;
const TAG = /\[([a-zA-Z]+)(?::\d+)?\[([^\]]*)\]/g;
const BISM_WORDS = ['بسم', 'الله', 'الرحمن', 'الرحيم'];

/** Разметка вида «[h:8078[ٱ]للَّهُ» -> [{text, cls}] */
function parseTajweedMarkup(raw) {
  const segs = [];
  let cursor = 0;
  for (const m of raw.matchAll(TAG)) {
    if (m.index > cursor) segs.push({ text: raw.slice(cursor, m.index).replace(SILENT_CIRCLE, ''), cls: null });
    segs.push({ text: (m[2] || '').replace(SILENT_CIRCLE, ''), cls: TAJWEED_CLASS[m[1].toLowerCase()] || null });
    cursor = m.index + m[0].length;
  }
  if (cursor < raw.length) segs.push({ text: raw.slice(cursor).replace(SILENT_CIRCLE, ''), cls: null });
  return segs;
}

/** Окрашивает «тяжёлые» буквы (ص ض ط ظ خ غ ق) вместе с их огласовкой — только в неразмеченном тексте */
function applyTafkhim(segs) {
  const out = [];
  for (const seg of segs) {
    if (seg.cls) { out.push(seg); continue; }
    const chars = [...seg.text];
    let buf = '';
    for (let i = 0; i < chars.length; i++) {
      if (HEAVY.has(chars[i])) {
        if (buf) { out.push({ text: buf, cls: null }); buf = ''; }
        let cluster = chars[i];
        while (i + 1 < chars.length && DIACRITIC.test(chars[i + 1])) cluster += chars[++i];
        out.push({ text: cluster, cls: 'tj-tafkhim' });
      } else buf += chars[i];
    }
    if (buf) out.push({ text: buf, cls: null });
  }
  return out;
}

/** API кладёт басмалу в начало первого аята каждой суры — убираем её, как и в основном тексте. */
function stripBismillah(segs) {
  const plain = segs.map((s) => s.text).join('');
  const words = plain.split(' ');
  if (words.length <= 4 || !BISM_WORDS.every((w, i) => normAr(words[i]) === w)) return segs;
  let cut = words.slice(0, 4).join(' ').length + 1;
  const out = [];
  for (const s of segs) {
    if (cut <= 0) out.push(s);
    else if (s.text.length <= cut) cut -= s.text.length;
    else { out.push({ ...s, text: s.text.slice(cut) }); cut = 0; }
  }
  return out;
}

const segmentsToHtml = (segs) =>
  segs.map((s) => (s.cls ? `<span class="${s.cls}">${esc(s.text)}</span>` : esc(s.text))).join('');

const tajweedCache = new Map();
/** Карта «номер аята -> HTML с подсветкой» для суры. Бросает ошибку при проблемах сети. */
function fetchTajweed(surah) {
  if (!tajweedCache.has(surah)) {
    const p = getJSON(`https://api.alquran.cloud/v1/surah/${surah}/quran-tajweed`, 9000).then((j) => {
      const ayahs = j?.data?.ayahs;
      if (!Array.isArray(ayahs)) throw new Error('неожиданный ответ сервера');
      const map = {};
      for (const a of ayahs) {
        if (typeof a.numberInSurah !== 'number' || typeof a.text !== 'string') continue;
        let segs = parseTajweedMarkup(a.text);
        if (a.numberInSurah === 1 && surah !== 1 && surah !== 9) segs = stripBismillah(segs);
        map[a.numberInSurah] = segmentsToHtml(applyTafkhim(segs));
      }
      return map;
    });
    p.catch(() => tajweedCache.delete(surah));
    tajweedCache.set(surah, p);
  }
  return tajweedCache.get(surah);
}

/* ───────── Тафсир ───────── */
const TAFSIR_BASE = 'https://cdn.jsdelivr.net/gh/spa5k/tafsir_api@main/tafsir/ru-tafsir-ibne-kahtir';
const tafsirCache = new Map();

function cleanTafsir(t) {
  return String(t ?? '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n\n').replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').trim();
}
/** Приводит ответ источника к карте {номер аята: текст} — поддерживает массив и обёртки */
function tafsirMap(j) {
  const list = Array.isArray(j) ? j : Array.isArray(j?.ayahs) ? j.ayahs : null;
  const map = {};
  if (list) {
    for (const x of list) if (x && x.ayah != null && x.text != null) map[+x.ayah] = cleanTafsir(x.text);
  } else if (j && typeof j === 'object') {
    for (const [k, v] of Object.entries(j)) {
      if (/^\d+$/.test(k)) map[+k] = cleanTafsir(typeof v === 'string' ? v : v?.text);
    }
  }
  return map;
}
function fetchTafsirSurah(surah) {
  if (!tafsirCache.has(surah)) {
    const p = getJSON(`${TAFSIR_BASE}/${surah}.json`, 15000).then(tafsirMap);
    p.catch(() => tafsirCache.delete(surah));
    tafsirCache.set(surah, p);
  }
  return tafsirCache.get(surah);
}
/** Текст тафсира к аяту или null, если источник не содержит его. Бросает ошибку при проблемах сети. */
async function getTafsir(surah, ayah) {
  try {
    const map = await fetchTafsirSurah(surah);
    if (map[ayah]) return map[ayah];
    if (Object.keys(map).length) return null;
  } catch (e) {
    // файл суры недоступен — пробуем файл отдельного аята
    try {
      const j = await getJSON(`${TAFSIR_BASE}/${surah}/${ayah}.json`, 10000);
      const t = cleanTafsir(j?.text);
      return t || null;
    } catch { throw e; }
  }
  return null;
}

return { parseTajweedMarkup, segmentsToHtml, fetchTajweed, getTafsir };
})();

/* ── screens/quran.js ── */
const __m_screens_quran = (() => {
const { icon, esc, $, $$, toast, starBadge, openSheet, switchEl, bindSwitches, copyText, promptDialog, hl, emptyState, plural, arDigits, clamp } = __m_core_ui;
const { getSettings, setSettings, getBookmarks, toggleBookmark, isBookmarked, removeBookmark, addBookmarkRaw, getLastRead, setLastRead, getNote, setNote, getNotes } = __m_core_store;
const { getQuran, getHadiths, orderedSurahs, searchQuran, juzOf, ayahCopyText, relatedHadiths } = __m_core_data;
