  if (!s) { view.innerHTML = emptyState('Такой суры нет', 'Выберите суру из списка.', '<a class="btn" style="margin-top:14px" href="#/quran">К списку</a>'); return; }
  const st = getSettings();
  const ordered = orderedSurahs(surahs);
  const pos = ordered.indexOf(s);
  const prev = ordered[pos - 1], next = ordered[pos + 1];
  const j0 = juzOf(n, 1);
  const showBism = n !== 1 && n !== 9;
  const total = s.ayahs.length;

  const ayahCard = (ar, ru, i) => {
    const a = i + 1, bm = isBookmarked(n, a), note = getNote(n, a);
    return `<article class="ayah" id="a${a}" data-a="${a}">
      <div class="a-head"><span class="a-num">${a}</span><div class="a-acts">
        <button class="icon-btn" data-act="play" aria-label="Слушать аят ${a}">${icon('play')}</button>
        <button class="icon-btn" data-act="bm" aria-pressed="${bm}" aria-label="Закладка: аят ${a}">${icon('bookmark')}</button>
        <button class="icon-btn" data-act="tafsir" aria-label="Тафсир к аяту ${a}">${icon('info')}</button>
        <button class="icon-btn" data-act="more" aria-label="Другие действия: аят ${a}">${icon('list')}</button></div></div>
      ${st.showAr ? `<div class="a-ar" lang="ar" dir="rtl" data-ar="${a}">${esc(ar)}</div>` : ''}
      ${st.showRu ? `<p class="a-ru">${esc(ru)}</p>` : ''}
      ${note ? `<button class="a-note" data-act="note">${icon('note')}<span>${esc(note)}</span></button>` : ''}
    </article>`;
  };
  const flowHTML = () => `<div class="flow" lang="ar" dir="rtl">${s.ayahs.map(([ar], i) =>
    `<span class="fa" id="a${i + 1}" data-a="${i + 1}" data-ar="${i + 1}" tabindex="0" role="button" aria-label="Аят ${i + 1}">${esc(ar)}</span><span class="fnum">﴿${arDigits(i + 1)}﴾</span> `).join('')}</div>
    <p class="page-sub flow-hint">Нажмите на аят, чтобы открыть действия</p>`;

  view.innerHTML = `
    <div class="r-bar">
      <a class="icon-btn" href="#/quran" aria-label="К списку сур">${icon('back')}</a>
      <button class="r-title" id="pick" aria-label="Выбрать суру"><b>${n}. ${esc(s.ru)}</b><small>Джуз ${j0} · ${total} ${plural(total, 'аят', 'аята', 'аятов')} ${icon('down')}</small></button>
      <div class="r-actions">
        <button class="icon-btn" id="play-surah" aria-label="Слушать суру целиком">${icon('play')}</button>
        <button class="icon-btn" id="flow-btn" aria-pressed="${st.flow}" aria-label="Режим сплошного текста">${icon('quran')}</button>
        <button class="icon-btn" id="read-set" aria-label="Настройки чтения">${icon('sliders')}</button>
      </div></div>
    <div class="s-banner">
      <div class="ar" lang="ar">${esc(s.ar)}</div><h1>${esc(s.ru)}</h1>
      <p>${esc(s.meaning)} · ${s.type === 'Мекканская' ? 'Мекканская' : 'Мединская'} · ${total} ${plural(total, 'аят', 'аята', 'аятов')}</p>
      <button class="chip-btn" id="about">${icon('info')} О суре</button>
    </div>
    ${showBism && st.showAr ? `<div class="bism" lang="ar" dir="rtl">${BISM}</div>` : ''}
    <div id="ayahs" class="${st.showRu ? '' : 'no-ru'}">${st.flow && st.showAr ? flowHTML() : s.ayahs.map(([ar, ru], i) => ayahCard(ar, ru, i)).join('')}</div>
    <div class="r-nav">
      ${prev ? `<a class="btn" href="#/quran/${prev.n}">${icon('back')} ${esc(prev.ru)}</a>` : ''}
      ${next ? `<a class="btn" href="#/quran/${next.n}">${esc(next.ru)} ${icon('forward')}</a>` : ''}
    </div>`;

  setLastRead(n, focusAyah || 1);

  /* — подсветка таджвида — */
  if (st.tajweed && st.showAr) {
    fetchTajweed(n).then((map) => {
      if (!view.isConnected || $('#ayahs', view) == null) return;
      for (const el of $$('[data-ar]', view)) { const h = map[+el.dataset.ar]; if (h) el.innerHTML = h; }
    }).catch(() => toast('Таджвид недоступен: нет связи с alquran.cloud'));
  }

  /* — прокрутка к аяту — */
  if (focusAyah > 0) {
    const el = $('#a' + clamp(focusAyah, 1, total), view);
    if (el) requestAnimationFrame(() => { el.scrollIntoView({ block: 'start' }); el.classList.add('flash'); });
  } else window.scrollTo(0, 0);

  /* — запоминаем место чтения — */
  let io = null, ioTimer;
  if ('IntersectionObserver' in window) {
    io = new IntersectionObserver((entries) => {
      for (const e of entries) {
        if (!e.isIntersecting) continue;
        clearTimeout(ioTimer);
        const a = +e.target.dataset.a;
        ioTimer = setTimeout(() => setLastRead(n, a), 700);
      }
    }, { rootMargin: '-15% 0px -75% 0px' });
    $$('[data-a]', view).forEach((el) => io.observe(el));
  }

  /* — подсветка играющего аята; в режиме «Коран-плеер» следуем за плеером в следующую суру — */
  let lastAyah = 0, wasHere = false;
  const offAudio = onAudio((a) => {
    $$('.playing', view).forEach((el) => el.classList.remove('playing'));
    const pb = $('#play-surah', view);
    const here = a.surah === n;
    if (pb) pb.innerHTML = icon(a.playing && here ? 'pause' : 'play');
    if (here) wasHere = true;
    if (a.playing && !here && a.surah && a.continuous && wasHere) { location.hash = `#/quran/${a.surah}`; return; }
    if (a.playing && here) {
      const el = $('#a' + a.ayah, view);
      if (el) {
        el.classList.add('playing');
        if (a.ayah !== lastAyah) { lastAyah = a.ayah; el.scrollIntoView({ block: 'center', behavior: 'smooth' }); }
      }
    } else if (!a.playing) lastAyah = 0;
  });

  const rerender = () => {
    const y = window.scrollY;
    renderReader(view, n, 0).then(() => window.scrollTo(0, y));
  };

  /* — события — */
  view.onclick = (e) => {
    const t = e.target;
    if (t.closest('#pick')) return openPicker(surahs, n, ordered);
    if (t.closest('#about')) return openAbout(s);
    if (t.closest('#read-set')) return openReadSettings(rerender);
    if (t.closest('#flow-btn')) { setSettings({ flow: !getSettings().flow }); return rerender(); }
    if (t.closest('#play-surah')) {
      const a = getAudio();
      if (a.surah === n && (a.playing || a.loading)) return togglePlay();
      return playRange({ surah: n, from: 1, to: total });
    }
    const fa = t.closest('.fa');
    if (fa) return openAyahActions(surahs, n, +fa.dataset.a, rerender);
    const act = t.closest('[data-act]');
    if (!act) return;
    const art = act.closest('[data-a]');
    const a = +art.dataset.a;
    switch (act.dataset.act) {
      case 'play': return playRange({ surah: n, from: a, to: total });
      case 'bm': {
        const on = toggleBookmark(n, a, s.ru);
        act.setAttribute('aria-pressed', on);
        if (on) setLastRead(n, a);
        return toast(on ? `Закладка: ${s.ru}, аят ${a}` : 'Закладка убрана');
      }
      case 'tafsir': return openTafsir(surahs, n, a);
      case 'more': return openAyahActions(surahs, n, a, rerender);
      case 'note': return editNote(n, a, rerender);
    }
  };
  view.onkeydown = (e) => {
    if ((e.key === 'Enter' || e.key === ' ') && e.target.classList?.contains('fa')) { e.preventDefault(); openAyahActions(surahs, n, +e.target.dataset.a, rerender); }
  };
  return () => { io?.disconnect(); clearTimeout(ioTimer); offAudio(); view.onclick = null; view.onkeydown = null; };
}

/* ───── Панели ───── */
function openAbout(s) {
  openSheet(`${s.n}. ${s.ru}`, `
    <div class="chips"><span class="chip">Тип: ${esc(s.type)}</span><span class="chip">Аятов: ${s.ayahs.length}</span><span class="chip">Джуз ${juzOf(s.n, 1)}</span></div>
    <p class="about-ar" lang="ar">${esc(s.ar)}</p>
    <h3 class="sub-h">Значение названия</h3><p class="muted-p">${esc(s.meaning)}</p>
    ${s.info ? `<h3 class="sub-h">Смысловой контекст</h3><p class="muted-p">${esc(s.info)}</p>` : ''}`);
}

function openPicker(surahs, current, ordered) {
  openSheet('Перейти', `
    <div class="search" style="margin-bottom:10px">${icon('search')}<input id="pk-q" type="search" placeholder="Название или номер суры" autocomplete="off"></div>
    <div class="goto-row"><label for="pk-a">Аят</label><input class="field" id="pk-a" type="number" min="1" max="${surahs[current - 1].ayahs.length}" placeholder="№"><button class="btn" id="pk-go">Перейти к аяту</button></div>
    <ul class="surah-list pick-list" id="pk-list"></ul>`, (root, close) => {
    const list = $('#pk-list', root), q = $('#pk-q', root);
    const paint = () => {
      const v = q.value.trim().toLowerCase();
      const items = ordered.filter((x) => !v || x.ru.toLowerCase().includes(v) || String(x.n) === v || x.meaning.toLowerCase().includes(v));
      list.innerHTML = items.map((x) => `<li><a class="srow ${x.n === current ? 'cur' : ''}" href="#/quran/${x.n}" data-close>${starBadge(x.n)}<span class="sname"><b>${esc(x.ru)}</b><small>${esc(x.meaning)}</small></span><span class="sar" lang="ar">${esc(x.ar)}</span></a></li>`).join('');
    };
    q.oninput = paint; paint();
    $('#pk-go', root).onclick = () => {
      const a = +$('#pk-a', root).value;
      if (!a || a < 1 || a > surahs[current - 1].ayahs.length) return toast(`Введите номер аята от 1 до ${surahs[current - 1].ayahs.length}`);
      close();
      location.hash = `#/quran/${current}/${a}`;
    };
  });
}

function openReadSettings(rerender) {
  const s = getSettings();
  const html = `
    <div class="preview"><div class="a-ar" id="pv-ar" lang="ar" dir="rtl">بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ</div><p class="a-ru" id="pv-ru">Во имя Аллаха, Милостивого, Милосердного!</p></div>
    <div class="row"><span class="lbl">Арабский текст</span>${switchEl(s.showAr, 'sw-ar', 'Арабский текст')}</div>
    <div class="row"><span class="lbl">Перевод на русский</span>${switchEl(s.showRu, 'sw-ru', 'Перевод')}</div>
    <div class="row"><span class="lbl">Цветные подсказки таджвида<small>Нужен интернет (alquran.cloud)</small></span>${switchEl(s.tajweed, 'sw-tj', 'Таджвид')}</div>
    <div class="row"><span class="lbl"></span><button class="btn ghost" id="tj-legend" style="min-height:38px;padding:0 14px">Что означают цвета?</button></div>
    <div class="row"><span class="lbl">Хронологическое чтение<small>Суры в порядке ниспослания, а не по Мусхафу</small></span>${switchEl(s.chrono, 'sw-ch', 'Хронологический порядок')}</div>
    <div class="row"><span class="lbl">Режим «Коран-плеер»<small>После конца суры плеер сам включает следующую</small></span>${switchEl(s.continuous, 'sw-co', 'Коран-плеер')}</div>
    <div class="row"><label for="r-ar">Арабский шрифт<small id="v-ar">${s.arSize} px</small></label><input class="range" id="r-ar" type="range" min="22" max="56" step="2" value="${s.arSize}"></div>
    <div class="row"><label for="r-ru">Перевод<small id="v-ru">${s.ruSize} px</small></label><input class="range" id="r-ru" type="range" min="13" max="26" value="${s.ruSize}"></div>
    <div class="row"><label for="r-tf">Тафсир<small id="v-tf">${s.tafsirSize} px</small></label><input class="range" id="r-tf" type="range" min="13" max="26" value="${s.tafsirSize}"></div>
    <div class="row"><span class="lbl">Хатм-план<small>Чтение всего Корана по дням</small></span><a class="btn ghost" href="#/tracker/khatm" data-close style="min-height:38px;padding:0 14px">Открыть</a></div>`;
  let dirty = false;
  const myHash = location.hash;
  openSheet('Настройки чтения', html, (root) => {
    bindSwitches(root, (id, on) => {
      const key = { 'sw-ar': 'showAr', 'sw-ru': 'showRu', 'sw-tj': 'tajweed', 'sw-ch': 'chrono', 'sw-co': 'continuous' }[id];
      setSettings({ [key]: on });
      dirty = true;
    });
    $('#tj-legend', root).onclick = () => openLegend();
    const slide = (id, key, out) => { $(id, root).oninput = (e) => { setSettings({ [key]: +e.target.value }); $(out, root).textContent = e.target.value + ' px'; applyReadingVars(); }; };
    slide('#r-ar', 'arSize', '#v-ar'); slide('#r-ru', 'ruSize', '#v-ru'); slide('#r-tf', 'tafsirSize', '#v-tf');
  }, { onClose: () => { if (dirty) setTimeout(() => { if (location.hash === myHash) rerender(); }, 60); } });
}

function openLegend() {
  openSheet('Цвета таджвида', `<ul class="legend">${TAJWEED_LEGEND.map(([cls, t]) => `<li><span class="dot ${cls}"></span>${esc(t)}</li>`).join('')}</ul>
    <p class="muted-p small">Разметка правил — Tajweed Guide сервиса Al Quran Cloud. Тафхим выделяется только для всегда «тяжёлых» букв (ص ض ط ظ خ غ ق).</p>`);
}

/* ───── Действия над аятом ───── */
function openAyahActions(surahs, n, a, rerender) {
  const s = surahs[n - 1];
  const bm = isBookmarked(n, a), hasNote = !!getNote(n, a);
  openSheet(`${s.ru} · аят ${a}`, `
    <div class="act-list">
      <button data-x="copy">${icon('copy')}<span>Копировать</span></button>
      <button data-x="play">${icon('play')}<span>Прослушать</span></button>
      <button data-x="tafsir">${icon('info')}<span>Тафсир Ибн Касира</span></button>
      <button data-x="share">${icon('share')}<span>Поделиться картинкой</span></button>
      <button data-x="note">${icon('edit')}<span>Заметка${hasNote ? '<small>Есть сохранённая заметка</small>' : ''}</span></button>
      <button data-x="bm">${icon('bookmark')}<span>${bm ? 'Убрать закладку' : 'Добавить в закладки'}</span></button>
    </div>`, (root, close) => {
    root.addEventListener('click', async (e) => {
      const b = e.target.closest('[data-x]');
      if (!b) return;
      close();
      switch (b.dataset.x) {
        case 'copy': toast((await copyText(ayahCopyText(s, a))) ? 'Аят скопирован' : 'Не удалось скопировать'); break;
        case 'play': openAudioRange(surahs, n, a); break;
        case 'tafsir': openTafsir(surahs, n, a); break;
        case 'share': openShareCard(s, a); break;
        case 'note': editNote(n, a, rerender); break;
        case 'bm': {
          const on = toggleBookmark(n, a, s.ru);
          toast(on ? `Закладка: ${s.ru}, аят ${a}` : 'Закладка убрана');
          rerender();
          break;
        }
      }
    });
  }, { done: false });
}

async function editNote(n, a, rerender) {
  const cur = getNote(n, a);
  const v = await promptDialog(`Заметка · аят ${a}`, { value: cur, placeholder: 'Ваши мысли об этом аяте…', multiline: true, extra: cur ? 'Удалить' : '' });
  if (v === null) return;
  setNote(n, a, v);
  toast(v.trim() ? 'Заметка сохранена' : 'Заметка удалена');
  rerender?.();
}

function openAudioRange(surahs, n, a) {
  const s = surahs[n - 1], total = s.ayahs.length, cur = getSettings();
  const opts = (from, sel) => Array.from({ length: total - from + 1 }, (_, i) => from + i).map((v) => `<option ${v === sel ? 'selected' : ''}>${v}</option>`).join('');
  openSheet(`Аудио: ${s.ru}`, `
    <div class="row stack"><label for="au-r">Чтец</label><select class="field wide" id="au-r">${RECITERS.map((r) => `<option value="${r.id}" ${r.id === cur.reciter ? 'selected' : ''}>${esc(r.ru)}</option>`).join('')}</select></div>
    <div class="goto-row"><label for="au-a">Аят от</label><select class="field" id="au-a">${opts(1, a)}</select><label for="au-b">до</label><select class="field" id="au-b">${opts(a, total)}</select></div>
    <button class="btn" id="au-go" style="width:100%;margin-top:12px">${icon('play')} Включить прослушивание</button>`, (root, close) => {
    const from = $('#au-a', root), to = $('#au-b', root);
    from.onchange = () => { const f = +from.value, t = Math.max(f, +to.value); to.innerHTML = opts(f, t); };
    $('#au-go', root).onclick = () => {
      setSettings({ reciter: $('#au-r', root).value });
      playRange({ surah: n, from: +from.value, to: +to.value });
      close();
    };
  }, { done: false });
}

/* ───── Тафсир ───── */
function openTafsir(surahs, n0, a0) {
  let n = n0, a = a0, token = 0, hadiths = null;
  const html = '<div id="tf-root"></div>';
  openSheet('', html, (root) => {
    const host = $('#tf-root', root);
    const draw = async () => {
      const my = ++token, s = surahs[n - 1];
      host.innerHTML = `
        <h2 class="tf-title">Тафсир Ибн Касира · ${esc(s.ru)}, аят ${a}</h2>
        <div class="tf-ayah" lang="ar" dir="rtl">${esc(s.ayahs[a - 1][0])}</div>
        <div class="tf-body" id="tf-body"><div class="skel" style="height:120px"></div></div>
        <div class="two-btns" style="margin-top:12px">
          <button class="btn ghost" id="tf-prev" ${n === 1 && a === 1 ? 'disabled' : ''}>${icon('back')} Предыдущий</button>
          <button class="btn ghost" id="tf-next" ${n === 114 && a === surahs[113].ayahs.length ? 'disabled' : ''}>Следующий ${icon('forward')}</button></div>
        <button class="btn" data-close style="width:100%;margin-top:10px">Готово</button>`;
      $('#tf-prev', host).onclick = () => { if (a > 1) a--; else if (n > 1) { n--; a = surahs[n - 1].ayahs.length; } draw(); };
      $('#tf-next', host).onclick = () => { if (a < s.ayahs.length) a++; else if (n < 114) { n++; a = 1; } draw(); };
      const body = $('#tf-body', host);
      try {
        const text = await getTafsir(n, a);
        if (my !== token) return;
        let rel = '';
        try {
          hadiths ||= await getHadiths();
          const r = relatedHadiths(s.ayahs[a - 1][1], hadiths);
          if (r.length) rel = `<div class="rel"><h3 class="sub-h">${icon('quote')} Возможно, по теме — хадисы</h3><p class="muted-p small">Подборка по совпадению слов, не богословское заключение</p>
            ${r.map((h) => `<a class="rel-i" href="#/hadith/${encodeURIComponent(h.bookId + ':' + h.number)}" data-close>${icon('forward')}<span>${esc(h.title)}</span></a>`).join('')}</div>`;
        } catch { /* хадисы не загрузились — блок пропускаем */ }
        if (text) {
          body.innerHTML = `<div class="tf-text">${esc(text)}</div><button class="btn ghost" id="tf-copy" style="margin-top:10px">${icon('copy')} Копировать аят и тафсир</button>${rel}`;
          $('#tf-copy', host).onclick = async () => {
            toast((await copyText(`Сура ${s.ru}, аят ${a}\n\n${s.ayahs[a - 1][0]}\n\nТафсир Ибн Касира:\n${text}`)) ? 'Скопировано: аят и тафсир' : 'Не удалось скопировать');
          };
        } else body.innerHTML = `<p class="muted-p">Для этого аята толкование пока недоступно в источнике.</p>${rel}`;
      } catch (e) {
        if (my !== token) return;
        body.innerHTML = `<p class="muted-p">Не удалось загрузить тафсир. Проверьте интернет и попробуйте ещё раз.<br><small>${esc(e.message || e)}</small></p><button class="btn" id="tf-retry" style="margin-top:10px">Повторить</button>`;
        $('#tf-retry', host).onclick = draw;
      }
    };
    draw();
  }, { done: false });
}

/* ───── Картинка для публикации ───── */
function wrapLines(ctx, text, maxW) {
  const words = text.split(' '), lines = [];
  let line = '';
  for (const w of words) {
    const test = line ? line + ' ' + w : w;
    if (ctx.measureText(test).width > maxW && line) { lines.push(line); line = w; } else line = test;
  }
  if (line) lines.push(line);
  return lines;
}
function drawCard(canvas, s, a) {
  const [ar, ru] = s.ayahs[a - 1];
  const W = 720, P = 56, ctx = canvas.getContext('2d');
  canvas.width = W;
  ctx.direction = 'rtl'; ctx.font = '44px "Amiri Quran","Noto Naskh Arabic","Scheherazade New",serif';
  const arLines = wrapLines(ctx, ar, W - P * 2);
  ctx.direction = 'ltr'; ctx.font = '28px Inter,system-ui,sans-serif';
  const ruLines = wrapLines(ctx, ru, W - P * 2);
  const H = P + 40 + 40 + arLines.length * 78 + 40 + ruLines.length * 40 + 50 + P;
  canvas.height = H;
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, '#174238'); g.addColorStop(1, '#0D2520');
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'rgba(200,169,126,.45)'; ctx.lineWidth = 3; ctx.strokeRect(14, 14, W - 28, H - 28);
  ctx.textAlign = 'center';
  let y = P + 20;
  ctx.direction = 'ltr'; ctx.fillStyle = 'rgba(200,169,126,.8)'; ctx.font = '600 24px Lora,Georgia,serif';
  if ('letterSpacing' in ctx) ctx.letterSpacing = '8px';
  ctx.fillText('СВЕТ', W / 2, y);
  if ('letterSpacing' in ctx) ctx.letterSpacing = '0px';
  y += 60;
  ctx.direction = 'rtl'; ctx.fillStyle = '#C8A97E'; ctx.font = '44px "Amiri Quran","Noto Naskh Arabic","Scheherazade New",serif';
  for (const l of arLines) { ctx.fillText(l, W / 2, y); y += 78; }
  y += 6;
  ctx.fillStyle = 'rgba(200,169,126,.45)'; ctx.fillRect(W / 2 - 40, y - 24, 80, 2);
  y += 24;
  ctx.direction = 'ltr'; ctx.fillStyle = '#F3EBD9'; ctx.font = '28px Inter,system-ui,sans-serif';
  for (const l of ruLines) { ctx.fillText(l, W / 2, y); y += 40; }
  y += 24;
  ctx.fillStyle = 'rgba(243,235,217,.65)'; ctx.font = '600 22px Inter,system-ui,sans-serif';
  ctx.fillText(`${s.ru} • Аят ${a}`, W / 2, y);
}
function openShareCard(s, a) {
  openSheet('Поделиться аятом', `<canvas id="sc" class="share-canvas"></canvas>
    <div class="two-btns" style="margin-top:12px"><button class="btn ghost" data-close>Закрыть</button><button class="btn" id="sc-go">${icon('share')} Поделиться</button></div>`, (root) => {
    const canvas = $('#sc', root);
    const paint = () => drawCard(canvas, s, a);
    paint();
    if (document.fonts?.ready) document.fonts.ready.then(paint);
    $('#sc-go', root).onclick = () => {
      canvas.toBlob(async (blob) => {
        if (!blob) return toast('Не удалось создать картинку');
        const file = new File([blob], `ayah-${s.n}-${a}.png`, { type: 'image/png' });
        try {
          if (navigator.canShare?.({ files: [file] })) { await navigator.share({ files: [file], title: `${s.ru}, аят ${a}` }); return; }
        } catch (e) { if (e && e.name === 'AbortError') return; }
        const url = URL.createObjectURL(blob);
        const link = Object.assign(document.createElement('a'), { href: url, download: file.name });
        document.body.append(link); link.click(); link.remove();
        setTimeout(() => URL.revokeObjectURL(url), 2000);
        toast('Картинка сохранена');
      }, 'image/png');
    };
  }, { done: false });
}

return { applyReadingVars, renderQuran, renderReader, openReadSettings, openLegend, openAudioRange };
})();

/* ── screens/hifz.js ── */
const __m_screens_hifz = (() => {
const { icon, esc, $, $$, toast, openSheet, switchEl, bindSwitches, subbar, progressBar, emptyState, shuffle, plural } = __m_core_ui;
const { getSettings, setSettings, getMemorized, toggleMemorized, srsEnsureStarted, srsRemove, srsRecord, srsDueToday, srsDailySeed, getHifzPlan, setHifzPlan, getStreak, markStreakToday, getShownAchievements, markAchievementShown } = __m_core_store;
const { getQuran, juzSurahRange, overlapScore } = __m_core_data;
const { RECITERS } = __m_core_meta;
const { playAyah, playRange, stopAudio, onAudio, getAudio, togglePlay } = __m_core_audio;
const { openAudioRange } = __m_screens_quran;
const { dayKey, parseDay, addDays, startOfDay, fmtDMY, diffDays } = __m_core_time;
const { arDigits } = __m_core_ui;

let hTab = 'progress';
let audioMode = 'quiz';
let quizScore = { ok: 0, all: 0 };

/* ═════ Достижения: вычисляются из прогресса, хранится только факт показа сертификата ═════ */
const ACHIEVEMENTS = [
  { id: 'first_surah', title: 'Первый шаг', desc: 'Заучена первая сура', icon: 'star', ok: (m) => m.size > 0 },
  { id: 'juz_amma_short', title: 'Джуз Амма: начало', desc: '5 коротких сур заучено', icon: 'quran', ok: (m) => [...m].filter((n) => n >= 78).length >= 5 },
  { id: 'ten_surahs', title: '10 сур позади', desc: '10 сур заучено', icon: 'trophy', ok: (m) => m.size >= 10 },
  { id: 'streak_7', title: 'Неделя подряд', desc: '7 дней подряд занятий', icon: 'flame', ok: (m, s) => s >= 7 },
  { id: 'streak_30', title: 'Месяц постоянства', desc: '30 дней подряд занятий', icon: 'flame', ok: (m, s) => s >= 30 },
  { id: 'juz_amma_full', title: 'Джуз Амма целиком', desc: 'Все суры 30-го джуза заучены', icon: 'trophy', ok: (m) => Array.from({ length: 37 }, (_, i) => 78 + i).every((n) => m.has(n)) },
];
const achievementsList = () => ACHIEVEMENTS;
const unlockedAchievements = () => ACHIEVEMENTS.filter((a) => a.ok(getMemorized(), getStreak()));

function maybeShowAchievement() {
  const m = getMemorized(), streak = getStreak(), shown = getShownAchievements();
  const a = ACHIEVEMENTS.find((x) => !shown.has(x.id) && x.ok(m, streak));
  if (!a) return;
  markAchievementShown(a.id);
  openSheet('', `<div class="cert">${icon(a.icon)}<small>Новое достижение</small><h2>${esc(a.title)}</h2><p>${esc(a.desc)}</p></div>
    <button class="btn" data-close style="width:100%;margin-top:14px">Продолжить</button>`, null, { done: false });
}

/* ═════ Напоминание о перерыве (каждые 25 минут занятий) ═════ */
let breakTimer = null;
function startBreakTimer() {
  clearTimeout(breakTimer);
  if (!getSettings().hifzBreak) return;
  breakTimer = setTimeout(() => {
    openSheet('Пора отдохнуть', `<p class="muted-p" style="text-align:center">Мозг лучше запоминает после короткой паузы. Подышите в такт кругу пару минут — или просто закройте глаза на минуту.</p>
      <div class="breath"><div class="breath-c"><span></span></div></div>
      <button class="btn" data-close style="width:100%">Продолжить занятие</button>`, null, { done: false, onClose: startBreakTimer });
  }, 25 * 60 * 1000);
}
const stopBreakTimer = () => clearTimeout(breakTimer);

function openHifzSettings() {
  const s = getSettings();
  openSheet('Настройки Хифза', `
    <div class="row"><span class="lbl">Напоминание о перерыве<small>Мягкая пауза с дыхательным упражнением каждые 25 минут занятий</small></span>${switchEl(s.hifzBreak, 'sw-br', 'Напоминание о перерыве')}</div>
    <div class="row"><span class="lbl">Подсветка по смыслу (эксперимент)<small>Приблизительная подсветка тем по ключевым словам перевода — не научная разметка, а подсказка</small></span>${switchEl(s.hifzHighlight, 'sw-th', 'Подсветка по смыслу')}</div>`, (root) => {
    bindSwitches(root, (id, on) => {
      if (id === 'sw-br') { setSettings({ hifzBreak: on }); startBreakTimer(); } else setSettings({ hifzHighlight: on });
    });
  });
}

/* ═════ Главный экран Хифза ═════ */
async function renderHifz(view) {
  view.innerHTML = `${subbar('Хифз', '#/', `<button class="icon-btn" id="h-set" aria-label="Настройки Хифза">${icon('settings')}</button>`)}
    <div class="seg h-tabs" role="tablist">${[['progress', 'Прогресс'], ['test', 'Тест'], ['audio', 'Аудио']].map(([id, t]) => `<button role="tab" data-t="${id}" aria-selected="${hTab === id}">${t}</button>`).join('')}</div>
    <div id="hbody"><div class="skel" style="height:300px"></div></div>`;
  startBreakTimer();
  $('#h-set', view).onclick = openHifzSettings;
  $$('[data-t]', view).forEach((b) => { b.onclick = () => { hTab = b.dataset.t; renderHifz(view); }; });
  const body = $('#hbody', view);
  let surahs;
  try { surahs = await getQuran(); } catch { body.innerHTML = emptyState('Не удалось загрузить данные', 'Обновите страницу.'); return stopBreakTimer; }
  let cleanup = null;
  if (hTab === 'progress') cleanup = paintProgress(body, surahs);
  else if (hTab === 'test') cleanup = paintTest(body, surahs);
  else cleanup = paintAudio(body, surahs);
  return () => { stopBreakTimer(); cleanup?.(); };
}

/* ───── Прогресс ───── */
function paintProgress(body, surahs) {
  markStreakToday();
  const draw = () => {
    const mem = getMemorized(), plan = getHifzPlan(), streak = getStreak();
    const totalAyahs = surahs.reduce((t, s) => t + s.ayahs.length, 0);
    const memAyahs = surahs.filter((s) => mem.has(s.n)).reduce((t, s) => t + s.ayahs.length, 0);
    const percent = memAyahs / totalAyahs;
    let juzDone = 0;
    for (let j = 1; j <= 30; j++) {
      const [a, b] = juzSurahRange(j);
      let ok = true;
      for (let n = a; n <= b; n++) if (!mem.has(n)) { ok = false; break; }
      if (ok) juzDone++;
    }
    const planFrac = plan.active ? Math.min(1, mem.size / plan.count) : 0;
    const due = srsDueToday().length;
    body.innerHTML = `
      <section class="hifz-hero"><span class="hifz-ico">${icon('hifz')}</span><h2>Мой хифз</h2><p>Сохраняй, повторяй, приближайся</p></section>
      <section class="card hifz-stats">
        ${plan.active ? `<div class="plan-row"><b>${mem.size} из ${plan.count} сур по плану</b><span>${Math.round(planFrac * 100)}%</span></div>${progressBar(planFrac, 'Выполнение плана')}
          ${plan.deadline ? `<small class="muted">Дедлайн: ${fmtDMY(parseDay(plan.deadline))}</small>` : ''}`
    : '<p class="muted-p">План не задан — учи в своём темпе или поставь цель</p>'}
        <div class="stats">
          <div><b>${streak}</b><span>${plural(streak, 'день', 'дня', 'дней')} подряд</span></div>
          <div><b>${mem.size}</b><span>сур выучено</span></div>
          <div><b>${(percent * 100).toFixed(2).replace('.', ',')}%</b><span>всего Корана</span></div>
          <div><b>${memAyahs}</b><span>аятов выучено</span></div>
          <div><b>${juzDone} / 30</b><span>джузов выучено</span></div>
        </div>
        <button class="btn" id="plan-btn" style="width:100%;margin-top:14px">${plan.active ? 'Изменить план' : 'Задать план'}</button>
      </section>
      <h2 class="card-h">Достижения</h2>
      <div class="ach-strip">${ACHIEVEMENTS.map((a) => {
    const on = a.ok(mem, streak);
    return `<div class="ach ${on ? 'on' : ''}" title="${esc(a.desc)}"><span>${icon(a.icon)}</span><small>${esc(a.title)}</small></div>`;
  }).join('')}</div>
      <div class="list-head"><h2 class="card-h" style="margin:0">Отметь заученные суры</h2>
        <button class="chip-btn" id="due-btn" aria-label="Пора повторить">${icon('repeat')} Повторить${due ? `<i class="badge">${due}</i>` : ''}</button></div>
      <ul class="hifz-list">${surahs.map((s) => {
    const done = mem.has(s.n);
    return `<li class="hrow ${done ? 'done' : ''}">
        <button class="chk" role="checkbox" aria-checked="${done}" data-chk="${s.n}" aria-label="${esc(s.ru)}: заучена">${icon('check')}</button>
        ${done ? `<a class="icon-btn" href="#/hifz/check/${s.n}" aria-label="Проверить по памяти: ${esc(s.ru)}">${icon('eyeoff')}</a>` : ''}
        <a class="hname" href="#/quran/${s.n}"><b>${s.n}. ${esc(s.ru)}</b><small>${s.ayahs.length} ${plural(s.ayahs.length, 'аят', 'аята', 'аятов')}</small></a>
        <span class="chev">${icon('forward')}</span></li>`;
  }).join('')}</ul>`;
  };
  draw();
  body.onclick = (e) => {
    const chk = e.target.closest('[data-chk]');
    if (chk) {
      const n = +chk.dataset.chk, s = surahs[n - 1];
      const on = toggleMemorized(n);
      if (on) { srsEnsureStarted(n); draw(); maybeShowAchievement(); } else {
        srsRemove(n); draw();
        toast(`«${s.ru}» убрана из заученных`, { label: 'Отменить', onClick: () => { toggleMemorized(n); srsEnsureStarted(n); draw(); } });
      }
      return;
    }
    if (e.target.closest('#plan-btn')) return openPlan(draw);
    if (e.target.closest('#due-btn')) return openDue(surahs, draw);
  };
  return () => { body.onclick = null; };
}

function openPlan(after) {
  const cur = getHifzPlan();
  const minD = fmtISO(addDays(startOfDay(), 1));
  const defD = cur.deadline || fmtISO(addDays(startOfDay(), 60));
  openSheet('План заучивания', `
    <div class="row stack"><label for="pl-n">Выучить сур: <b id="pl-v">${cur.count}</b></label><input class="range wide" id="pl-n" type="range" min="1" max="114" value="${cur.count}"></div>
    <div class="row stack"><label for="pl-d">Дедлайн</label><input class="field wide" id="pl-d" type="date" min="${minD}" value="${defD}"></div>
    <p class="muted-p small" id="pl-hint"></p>
    <div class="two-btns" style="margin-top:8px">${cur.active ? '<button class="btn ghost danger" id="pl-stop">Отменить план</button>' : '<button class="btn ghost" data-close>Закрыть</button>'}<button class="btn" id="pl-save">Сохранить</button></div>`, (root, close) => {
    const n = $('#pl-n', root), d = $('#pl-d', root);
    const hint = () => {
      $('#pl-v', root).textContent = n.value;
      const days = diffDays(startOfDay(), parseDay(d.value || defD));
      const left = Math.max(0, +n.value - getMemorized().size);
      $('#pl-hint', root).textContent = days > 0 && left > 0 ? `Осталось ${days} ${plural(days, 'день', 'дня', 'дней')}: примерно ${(left / (days / 7)).toFixed(1).replace('.', ',')} суры в неделю.` : '';
    };
    n.oninput = hint; d.oninput = hint; hint();
    $('#pl-save', root).onclick = () => {
      if (!d.value || parseDay(d.value) <= startOfDay()) return toast('Выберите дату в будущем');
      setHifzPlan({ active: true, count: +n.value, deadline: d.value, start: dayKey() });
      close(); after();
    };
    $('#pl-stop', root)?.addEventListener('click', () => { setHifzPlan({ active: false, count: 10, deadline: null, start: dayKey() }); close(); after(); });
  }, { done: false });
}
const fmtISO = (d) => dayKey(d);

function openDue(surahs, after) {
  srsDailySeed();
  const html = () => {
    const due = srsDueToday();
    return due.length ? due.map((n) => `<div class="due-row"><a href="#/hifz/check/${n}" data-close><b>${n}. ${esc(surahs[n - 1].ru)}</b></a>
      <button class="icon-btn ok" data-r="${n}:1" aria-label="Знаю хорошо">${icon('checkc')}</button>
      <button class="icon-btn warn" data-r="${n}:0" aria-label="Есть проблемы">${icon('refresh')}</button></div>`).join('')
      : '<p class="muted-p" style="padding:14px 0">Сегодня повторять нечего — всё по расписанию.</p>';
  };
  openSheet('Пора повторить', `<p class="muted-p small">Каждый день сюда добавляются новые 10 сур с конца Корана — плюс те, что подошли по расписанию. Отметьте, как вы знаете суру.</p><div id="due-list">${html()}</div>`, (root) => {
    root.addEventListener('click', (e) => {
      const b = e.target.closest('[data-r]');
      if (!b) return;
      const [n, ok] = b.dataset.r.split(':').map(Number);
      srsRecord(n, !!ok);
      $('#due-list', root).innerHTML = html();
    });
  }, { onClose: after });
}

/* ───── Тест: случайный аят ───── */
function paintTest(body, surahs) {
  let mode = 'surah', from = 1, to = 114, cur = null, showTr = false, isNext = false;
  const pool = () => {
    const [a, b] = mode === 'surah' ? [from, to] : [juzSurahRange(from)[0], juzSurahRange(to)[1]];
    return surahs.filter((s) => s.n >= a && s.n <= b && s.ayahs.length > 1);
  };
  const random = () => {
    const p = pool();
    if (!p.length) return;
    const s = p[Math.floor(Math.random() * p.length)];
    cur = { s: s.n, a: 1 + Math.floor(Math.random() * (s.ayahs.length - 1)) };
    showTr = false; isNext = false;
  };
  const next = () => {
    if (!cur) return;
    if (cur.a < surahs[cur.s - 1].ayahs.length) { cur = { s: cur.s, a: cur.a + 1 }; showTr = true; isNext = true; } else toast('Это последний аят этой суры');
  };
  const draw = () => {
    const opts = (lo, hi, sel) => Array.from({ length: hi - lo + 1 }, (_, i) => lo + i).map((v) => `<option value="${v}" ${v === sel ? 'selected' : ''}>${mode === 'surah' ? `${v}. ${esc(surahs[v - 1].ru)}` : `Джуз ${v}`}</option>`).join('');
    const max = mode === 'surah' ? 114 : 30;
    const s = cur && surahs[cur.s - 1];
    body.innerHTML = `
      <div class="seg" style="margin-top:12px"><button data-m="surah" aria-pressed="${mode === 'surah'}">По сурам</button><button data-m="juz" aria-pressed="${mode === 'juz'}">По джузам</button></div>
      <div class="card range-card"><div><label for="rq-a">${mode === 'surah' ? 'Сура от' : 'Джуз от'}</label><select class="field wide" id="rq-a">${opts(1, max, from)}</select></div>
        <div><label for="rq-b">${mode === 'surah' ? 'до' : 'до джуза'}</label><select class="field wide" id="rq-b">${opts(from, max, to)}</select></div></div>
      ${cur ? `<section class="quiz-card"><div class="qc-head"><span class="${isNext ? 'gold' : ''}">${isNext ? 'Следующий аят' : 'Продолжите чтение'}<br>Сура: ${esc(s.ru)}</span>
        <button class="icon-btn big" id="rq-play" aria-label="Слушать аят">${icon('play')}</button></div>
        <div class="a-ar qc-ar" lang="ar" dir="rtl">${esc(s.ayahs[cur.a - 1][0])} <span class="fnum">﴿${arDigits(cur.a)}﴾</span></div>
        ${showTr ? `<p class="a-ru" style="text-align:center">${esc(s.ayahs[cur.a - 1][1])}</p>` : '<button class="chip-btn" id="rq-tr" style="margin:6px auto 0;display:flex">Показать перевод</button>'}
      </section>` : emptyState('Нет аятов в выбранном диапазоне', 'Расширьте диапазон.')}
      <button class="btn ghost" id="rq-next" style="width:100%;margin-top:12px">Показать следующий аят</button>
      <button class="btn" id="rq-rand" style="width:100%;margin-top:8px">${icon('shuffle')} Случайный аят</button>`;
  };
  random(); draw();
  body.onclick = (e) => {
    const m = e.target.closest('[data-m]');
    if (m) { mode = m.dataset.m; from = 1; to = mode === 'surah' ? 114 : 30; random(); return draw(); }
    if (e.target.closest('#rq-rand')) { random(); return draw(); }
    if (e.target.closest('#rq-next')) { next(); return draw(); }
    if (e.target.closest('#rq-tr')) { showTr = true; return draw(); }
    if (e.target.closest('#rq-play') && cur) return openAudioRange(surahs, cur.s, cur.a);
  };
  body.onchange = (e) => {
    if (e.target.id === 'rq-a') { from = +e.target.value; if (from > to) to = from; random(); draw(); }
    if (e.target.id === 'rq-b') { to = +e.target.value; random(); draw(); }
  };
  return () => { body.onclick = null; body.onchange = null; };
}

/* ───── Аудио: квиз и практика ───── */
function paintAudio(body, surahs) {
  body.innerHTML = `<div class="seg" style="margin-top:12px"><button data-am="quiz" aria-pressed="${audioMode === 'quiz'}">Квиз</button><button data-am="practice" aria-pressed="${audioMode === 'practice'}">Практика</button></div><div id="abody"></div>`;
  const ab = $('#abody', body);
  let inner = audioMode === 'quiz' ? quizView(ab, surahs) : practiceView(ab, surahs);
  body.onclick = (e) => {
    const m = e.target.closest('[data-am]');
    if (!m || m.dataset.am === audioMode) return;
    inner?.(); stopAudio();
    audioMode = m.dataset.am;
    paintAudio(body, surahs);
  };
  return () => { inner?.(); body.onclick = null; stopAudio(); };
}

function practiceView(host, surahs) {
  const st = { s: 1, a: 1, b: Math.min(2, surahs[0].ayahs.length), rate: 1, rep: 3, rec: getSettings().reciter };
  const draw = () => {
    const total = surahs[st.s - 1].ayahs.length;
    const opts = (lo, hi, sel) => Array.from({ length: hi - lo + 1 }, (_, i) => lo + i).map((v) => `<option ${v === sel ? 'selected' : ''}>${v}</option>`).join('');
    host.innerHTML = `
      <div class="row stack"><label for="pr-s">Сура</label><select class="field wide" id="pr-s">${surahs.map((s) => `<option value="${s.n}" ${s.n === st.s ? 'selected' : ''}>${s.n}. ${esc(s.ru)}</option>`).join('')}</select></div>
      <div class="goto-row"><label for="pr-a">Аяты</label><select class="field" id="pr-a">${opts(1, total, st.a)}</select><span>—</span><select class="field" id="pr-b">${opts(st.a, total, st.b)}</select></div>
      <div class="row stack"><label for="pr-r">Скорость: <b id="pr-rv">${st.rate.toFixed(2)}×</b></label><input class="range wide" id="pr-r" type="range" min="0.5" max="1.5" step="0.05" value="${st.rate}"></div>
      <div class="row stack"><span class="lbl">Повторить диапазон: <b>${st.rep}</b> ${plural(st.rep, 'раз', 'раза', 'раз')}</span><div class="seg sm" id="pr-rep">${[1, 3, 5, 10].map((n) => `<button data-n="${n}" aria-pressed="${st.rep === n}">${n}</button>`).join('')}</div></div>
      <div class="row stack"><label for="pr-c">Чтец</label><select class="field wide" id="pr-c">${RECITERS.map((r) => `<option value="${r.id}" ${r.id === st.rec ? 'selected' : ''}>${esc(r.ru)}</option>`).join('')}</select></div>
      <p class="muted-p small" id="pr-status" style="text-align:center"></p>
      <button class="btn" id="pr-go" style="width:100%">${icon('play')} Начать прослушивание</button>`;
    status(getAudio());
  };
  const status = (a) => {
    const on = (a.playing || a.loading) && a.surah === st.s && a.from === st.a;
    const go = $('#pr-go', host), t = $('#pr-status', host);
    if (!go) return;
    go.innerHTML = on ? `${icon('stop')} Остановить` : `${icon('play')} Начать прослушивание`;
    t.textContent = on ? `Аят ${a.ayah} • повтор ${a.repeatTotal - a.repeatLeft + 1} из ${a.repeatTotal}` : '';
  };
  draw();
  const off = onAudio(status);
  host.onchange = (e) => {
    const id = e.target.id;
    if (id === 'pr-s') { st.s = +e.target.value; st.a = 1; st.b = Math.min(2, surahs[st.s - 1].ayahs.length); draw(); }
    else if (id === 'pr-a') { st.a = +e.target.value; st.b = Math.max(st.a, st.b); draw(); }
    else if (id === 'pr-b') st.b = +e.target.value;
    else if (id === 'pr-c') st.rec = e.target.value;
  };
  host.oninput = (e) => { if (e.target.id === 'pr-r') { st.rate = +e.target.value; $('#pr-rv', host).textContent = st.rate.toFixed(2) + '×'; } };
  host.onclick = (e) => {
    const rep = e.target.closest('#pr-rep button');
    if (rep) { st.rep = +rep.dataset.n; return draw(); }
    if (e.target.closest('#pr-go')) {
      const a = getAudio();
      if ((a.playing || a.loading) && a.surah === st.s) return stopAudio();
      playRange({ surah: st.s, from: st.a, to: st.b, repeat: st.rep, rate: st.rate, reciter: st.rec, continuous: false });
    }
  };
  return () => { off(); host.onchange = host.oninput = host.onclick = null; };
}

function quizView(host, surahs) {
  let q = null, answered = -1, rec = getSettings().reciter;
  const gen = () => {
    const cands = surahs.filter((s) => s.ayahs.length > 3);
    const s = cands[Math.floor(Math.random() * cands.length)];
    const idx = Math.floor(Math.random() * (s.ayahs.length - 1));
    const correct = { s: s.n, a: idx + 2, ar: s.ayahs[idx + 1][0], ru: s.ayahs[idx + 1][1] };
    const scored = [];
    for (const x of surahs) {
      for (let i = 0; i < x.ayahs.length; i++) {
        if (x.n === s.n && (i === idx || i === idx + 1)) continue;
        const sc = overlapScore(correct.ru, x.ayahs[i][1]);
        if (sc > 0) scored.push([sc, x.n, i]);
      }
    }
    scored.sort((p, r) => r[0] - p[0]);
    const top = shuffle(scored.slice(0, 40));
    const dist = [], seen = new Set([correct.ar]);
    for (const [, n, i] of top) {
      const ar = surahs[n - 1].ayahs[i][0];
      if (seen.has(ar)) continue;
      seen.add(ar); dist.push({ s: n, a: i + 1, ar });
      if (dist.length >= 3) break;
    }
    while (dist.length < 3) {
      const x = surahs[Math.floor(Math.random() * 114)], i = Math.floor(Math.random() * x.ayahs.length), ar = x.ayahs[i][0];
      if (!seen.has(ar)) { seen.add(ar); dist.push({ s: x.n, a: i + 1, ar }); }
    }
    q = { cur: { s: s.n, a: idx + 1 }, correct, options: shuffle([correct, ...dist]) };
    answered = -1;
  };
  const draw = () => {
    host.innerHTML = `
      <div class="row stack" style="margin-top:8px"><label for="qz-c">Чтец</label><select class="field wide" id="qz-c">${RECITERS.map((r) => `<option value="${r.id}" ${r.id === rec ? 'selected' : ''}>${esc(r.ru)}</option>`).join('')}</select></div>
      <p class="muted-p small" style="text-align:center">Сура ${esc(surahs[q.cur.s - 1].ru)} • Аят ${q.cur.a}</p>
      <div style="display:grid;place-items:center;margin:8px 0"><button class="play-big" id="qz-play" aria-label="Прослушать аят">${icon('play')}</button></div>
      <p class="muted-p small" style="text-align:center">Нажмите, чтобы прослушать аят</p>
      <h3 class="sub-h" style="margin-top:18px">Какой аят идёт следующим?</h3>
      ${q.options.map((o, i) => {
    const ok = o === q.correct;
    const cls = answered < 0 ? '' : ok ? 'right' : i === answered ? 'wrong' : '';
    return `<button class="opt ${cls}" data-o="${i}" ${answered >= 0 ? 'disabled' : ''}><span lang="ar" dir="rtl">${esc(o.ar)}</span></button>`;
  }).join('')}
      <p class="muted-p small" style="text-align:center">Верно: ${quizScore.ok} из ${quizScore.all}</p>
      ${answered >= 0 ? `<button class="btn" id="qz-next" style="width:100%;margin-top:6px">Следующий вопрос</button>` : ''}`;
  };
  gen(); draw();
  host.onclick = (e) => {
    if (e.target.closest('#qz-play')) {
      const a = getAudio();
      if (a.playing && a.surah === q.cur.s && a.ayah === q.cur.a) return togglePlay();
      return playAyah(q.cur.s, q.cur.a, { reciter: rec, continuous: false });
    }
    const o = e.target.closest('[data-o]');
    if (o && answered < 0) {
      answered = +o.dataset.o;
      quizScore.all++;
      if (q.options[answered] === q.correct) quizScore.ok++;
      return draw();
    }
    if (e.target.closest('#qz-next')) { gen(); draw(); }
  };
  host.onchange = (e) => { if (e.target.id === 'qz-c') rec = e.target.value; };
  const off = onAudio((a) => {
    const b = $('#qz-play', host);
    if (b) b.innerHTML = icon(a.playing && a.surah === q.cur.s && a.ayah === q.cur.a ? 'pause' : 'play');
  });
  return () => { off(); host.onclick = host.onchange = null; };
}

/* ═════ Проверка по памяти ═════ */
const THEMES = [
  ['th-paradise', (t) => t.includes('рай') || (t.includes('сад') && t.includes('блаж'))],
  ['th-hell', (t) => t.includes('ад') || t.includes('огон') || t.includes('наказан')],
  ['th-prophets', (t) => t.includes('пророк') || t.includes('муса') || t.includes('ибрахим') || t.includes('нух')],
  ['th-reflect', (t) => t.includes('размышля') || t.includes('разум') || t.includes('знамен')],
  ['th-law', (t) => t.includes('предпис') || t.includes('запрет') || t.includes('дозволен') || t.includes('закон')],
];
const themeOf = (ru) => { const t = ru.toLowerCase(); const h = THEMES.find(([, f]) => f(t)); return h ? h[0] : ''; };
const mask = (w) => '•'.repeat(Math.min(6, Math.max(2, w.length)));

async function renderCheck(view, n) {
  view.innerHTML = '<div class="skel" style="height:300px;margin-top:70px"></div>';
  let surahs;
  try { surahs = await getQuran(); } catch { view.innerHTML = emptyState('Не удалось загрузить данные', 'Обновите страницу.'); return; }
  const s = surahs[n - 1];
  if (!s) { view.innerHTML = emptyState('Такой суры нет', ''); return; }
  startBreakTimer();
  const hl = getSettings().hifzHighlight;
  let mode = 'hideAll';
  const revealed = new Set(), scr = new Map(), placed = new Map(), result = new Map();

  const card = (i) => {
    const a = i + 1, ar = s.ayahs[i][0], words = ar.split(' ');
    const th = hl ? themeOf(s.ayahs[i][1]) : '';
    const wrap = (inner) => `<article class="ccard ${th}" data-a="${a}">${inner}</article>`;
    if (mode === 'hideAll') {
      const open = revealed.has(a);
      return wrap(`<div class="cc-row"><div style="flex:1"><small class="muted">Аят ${a}</small><div class="cc-ar ${open ? '' : 'masked'}" lang="ar" dir="rtl">${esc(open ? ar : words.map(mask).join('   '))}</div></div>
        <button class="icon-btn" data-x="eye" aria-label="${open ? 'Скрыть аят' : 'Показать аят'}">${icon(open ? 'eye' : 'eyeoff')}</button></div>`);
    }
    if (mode === 'firstWordOnly') {
      return wrap(`<small class="muted">Аят ${a}</small><div class="cc-ar" lang="ar" dir="rtl">${words.map((w, k) => `<span class="${k ? 'masked' : ''}">${esc(k ? mask(w) : w)}</span>`).join(' ')}</div>`);
    }
    if (!scr.has(a)) scr.set(a, shuffle(words)); if (!placed.has(a)) placed.set(a, []);
    const sw = scr.get(a), pl = placed.get(a), res = result.get(a);
    const bank = sw.map((w, k) => k).filter((k) => !pl.includes(k));
    return wrap(`<div class="cc-row"><small class="muted">Аят ${a}</small>${pl.length ? '<button class="link-btn" data-x="reset">Заново</button>' : ''}</div>
      <div class="drop ${res === false ? 'bad' : res === true ? 'good' : ''}" lang="ar" dir="rtl">${pl.map((k) => `<button class="wd on" data-x="unplace" data-k="${k}" ${res != null ? 'disabled' : ''}>${esc(sw[k])}</button>`).join('')}</div>
      <div class="bank" lang="ar" dir="rtl">${bank.map((k) => `<button class="wd" data-x="place" data-k="${k}">${esc(sw[k])}</button>`).join('')}</div>
      ${!bank.length && pl.length && res == null ? '<button class="btn" data-x="check" style="width:100%;margin-top:10px">Проверить</button>' : ''}
      ${res === true ? '<p class="ok-t">Верно!</p>' : ''}${res === false ? '<p class="bad-t">Не совсем — попробуйте ещё раз</p>' : ''}`);
  };
  const paintAll = () => { $('#clist', view).innerHTML = s.ayahs.map((_, i) => card(i)).join(''); };
  const paintOne = (a) => { const el = $(`.ccard[data-a="${a}"]`, view); if (el) el.outerHTML = card(a - 1); };

  view.innerHTML = `${subbar('Проверка: ' + s.ru, '#/hifz', `<button class="icon-btn" id="c-mode" aria-label="Режим проверки">${icon('eyeoff')}</button>`)}
    <p class="page-sub" id="c-hint" style="margin:12px 0"></p><div id="clist"></div>`;
  const hints = { hideAll: 'Текст скрыт — вспомните аят и откройте его кнопкой-глазом.', firstWordOnly: 'Видно только первое слово каждого аята.', scramble: 'Слова перемешаны — расставьте их в правильном порядке.' };
  const setMode = (m) => { mode = m; revealed.clear(); scr.clear(); placed.clear(); result.clear(); $('#c-hint', view).textContent = hints[m]; paintAll(); };
  setMode('hideAll');

  view.onclick = (e) => {
    if (e.target.closest('#c-mode')) {
      return openSheet('Режим проверки', `<div class="act-list">
        <button data-m="hideAll">${icon('eyeoff')}<span>Скрыть текст всех аятов<small>На каждом аяте — кнопка-глаз</small></span></button>
        <button data-m="firstWordOnly">${icon('list')}<span>Скрыть аят, кроме первого слова</span></button>
        <button data-m="scramble">${icon('shuffle')}<span>Собрать аят<small>Слова перемешаны — расставьте их по порядку</small></span></button></div>`, (root, close) => {
        $$('[data-m]', root).forEach((b) => { if (b.dataset.m === mode) b.classList.add('sel'); });
        root.addEventListener('click', (ev) => { const b = ev.target.closest('[data-m]'); if (b) { close(); setMode(b.dataset.m); } });
      }, { done: false });
    }
    const x = e.target.closest('[data-x]');
    if (!x) return;
    const a = +x.closest('[data-a]').dataset.a, k = +x.dataset.k;
    switch (x.dataset.x) {
      case 'eye': revealed.has(a) ? revealed.delete(a) : revealed.add(a); break;
      case 'place': placed.get(a).push(k); result.delete(a); break;
      case 'unplace': placed.set(a, placed.get(a).filter((v) => v !== k)); result.delete(a); break;
      case 'reset': placed.set(a, []); result.delete(a); break;
      case 'check': {
        const right = s.ayahs[a - 1][0].split(' '), got = placed.get(a).map((i) => scr.get(a)[i]);
        result.set(a, got.length === right.length && got.every((w, i) => w === right[i]));
        break;
      }
    }
    paintOne(a);
  };
  return () => { stopBreakTimer(); view.onclick = null; };
}

return { achievementsList, unlockedAchievements, renderHifz, renderCheck };
})();

/* ── screens/settings.js ── */
const __m_screens_settings = (() => {
const { icon, esc, $, $$, toast, openSheet, switchEl, bindSwitches, promptDialog, confirmDialog } = __m_core_ui;
const { getSettings, setSettings, exportAll, importAll, resetAll, getMemorized, getStreak } = __m_core_store;
const { CITIES, PRAYER_METHODS, RECITERS } = __m_core_meta;
const { deviceTz } = __m_core_prayer;
const { askPermission, notificationsSupported, rescheduleNotifications } = __m_core_notify;
const { achievementsList } = __m_screens_hifz;
const { openReadSettings, applyReadingVars } = __m_screens_quran;
const { dayKey } = __m_core_time;

const APP_VERSION = '2.0.0';

/** Определяет местоположение через браузер. Возвращает true, если место обновлено. */
function detectLocation() {
  return new Promise((resolve) => {
    if (!navigator.geolocation) { toast('Браузер не умеет определять местоположение'); return resolve(false); }
    toast('Определяю местоположение…');
    navigator.geolocation.getCurrentPosition((p) => {
      setSettings({ loc: { name: 'Моё местоположение', lat: +p.coords.latitude.toFixed(4), lon: +p.coords.longitude.toFixed(4), tz: deviceTz(), chosen: true } });
      rescheduleNotifications();
      toast('Местоположение определено');
      resolve(true);
    }, (err) => {
      toast(err.code === 1 ? 'Доступ к местоположению запрещён — выберите город из списка' : 'Не удалось определить местоположение');
      resolve(false);
    }, { enableHighAccuracy: false, timeout: 12000, maximumAge: 600000 });
  });
}

/** Умный будильник: Фаджр / Тахаджуд / Сухур */
function openAlarmSheet(onChange) {
  const a = getSettings().alarm;
  openSheet('Умный будильник', `
    <div class="row"><span class="lbl">Фаджр</span>${switchEl(a.fajr, 'al-fajr', 'Фаджр')}</div>
    <div class="row"><span class="lbl">Тахаджуд<small>Начало последней трети ночи</small></span>${switchEl(a.tahajjud, 'al-tah', 'Тахаджуд')}</div>
    <div class="row"><span class="lbl">Сухур</span>${switchEl(a.suhur, 'al-suhur', 'Сухур')}</div>
    <div class="row" id="al-min-row" ${a.suhur ? '' : 'hidden'}><label for="al-min">За сколько минут до Фаджра</label>
      <select class="field" id="al-min">${[15, 20, 30, 45, 60].map((m) => `<option ${m === a.suhurMin ? 'selected' : ''}>${m}</option>`).join('')}</select></div>
    <p class="muted-p small">${notificationsSupported() ? 'В браузере уведомления приходят, только пока приложение открыто (вкладка или установленное PWA). Для будильника на ночь лучше системный будильник.' : 'Этот браузер не поддерживает уведомления.'}</p>`,
  (root) => {
    bindSwitches(root, async (id, on, sw) => {
      const key = { 'al-fajr': 'fajr', 'al-tah': 'tahajjud', 'al-suhur': 'suhur' }[id];
      if (on && !(await askPermission())) { sw.setAttribute('aria-checked', 'false'); return; }
      setSettings({ alarm: { ...getSettings().alarm, [key]: on } });
      if (key === 'suhur') $('#al-min-row', root).hidden = !on;
      rescheduleNotifications();
      onChange?.();
    });
    $('#al-min', root).onchange = (e) => {
      setSettings({ alarm: { ...getSettings().alarm, suhurMin: +e.target.value } });
      rescheduleNotifications();
    };
  });
}

async function renderSettings(view) {
  const s = getSettings();
  const known = CITIES.some(([n]) => n === s.loc.name);
  const notifOK = notificationsSupported();
  const unlocked = achievementsList().filter((a) => a.ok(getMemorized(), getStreak())).length;
  view.innerHTML = `
    <h1 class="page-title">Настройки</h1><p class="page-sub">Данные хранятся только в этом браузере</p>

    <h2 class="card-h">Профиль</h2>
    <div class="card">
      <button class="row link-row" id="s-name"><span class="lbl">Имя<small>${esc(s.userName || 'Не указано')}</small></span>${icon('forward')}</button>
      <button class="row link-row" id="s-mail"><span class="lbl">Почта<small>${esc(s.userEmail || 'Не указана')}</small></span>${icon('forward')}</button>
      <a class="row link-row" href="#/hifz"><span class="lbl">Достижения<small>Открыто ${unlocked} из ${achievementsList().length}</small></span>${icon('forward')}</a>
    </div>

    <h2 class="card-h">Оформление</h2>
    <div class="card"><div class="row"><span class="lbl">Тема</span>
      <div class="seg sm" id="theme" role="group" aria-label="Тема">${[['auto', 'Авто'], ['light', 'Светлая'], ['dark', 'Тёмная']].map(([v, t]) => `<button data-v="${v}" aria-pressed="${s.theme === v}">${t}</button>`).join('')}</div></div>
      <button class="row link-row" id="s-read"><span class="lbl">Чтение Корана<small>Шрифты, перевод, таджвид, порядок сур</small></span>${icon('forward')}</button></div>

    <h2 class="card-h">Намаз</h2>
    <div class="card">
      <div class="row"><label for="city">Город<small id="loc-sub">${s.loc.lat.toFixed(3)}, ${s.loc.lon.toFixed(3)}</small></label>
        <select class="field" id="city">${!known ? `<option value="__cur" selected>${esc(s.loc.name)}</option>` : ''}${CITIES.map(([n]) => `<option ${n === s.loc.name ? 'selected' : ''}>${esc(n)}</option>`).join('')}</select></div>
      <div class="row"><span class="lbl">Моё местоположение<small>Координаты остаются в этом браузере</small></span><button class="btn ghost" id="geo" style="min-height:40px;padding:0 14px">${icon('pin')} Определить</button></div>
      <div class="row stack"><label for="method">Метод расчёта времени</label>
        <select class="field wide" id="method">${PRAYER_METHODS.map((m) => `<option value="${m.id}" ${m.id === s.method ? 'selected' : ''}>${esc(m.ru)}</option>`).join('')}</select></div>
      <div class="row"><span class="lbl">Аср по ханафитскому мазхабу<small>Тень предмета вдвое длиннее самого предмета</small></span>${switchEl(s.asrHanafi, 'sw-hanafi', 'Ханафитский Аср')}</div>
      <div class="row"><span class="lbl">Напоминать о намазе<small>${notifOK ? 'Сработает, пока приложение открыто' : 'Браузер не поддерживает уведомления'}</small></span>${switchEl(s.notify && notifOK, 'sw-notify', 'Напоминать о намазе')}</div>
      <button class="row link-row" id="s-alarm"><span class="lbl">Умный будильник<small>Фаджр, Тахаджуд, Сухур</small></span>${icon('forward')}</button>
      <a class="row link-row" href="#/schedule"><span class="lbl">Расписание на месяц</span>${icon('forward')}</a>
    </div>

    <h2 class="card-h">Аудио</h2>
    <div class="card"><div class="row stack"><label for="reciter">Чтец по умолчанию</label>
      <select class="field wide" id="reciter">${RECITERS.map((r) => `<option value="${r.id}" ${r.id === s.reciter ? 'selected' : ''}>${esc(r.ru)}</option>`).join('')}</select></div></div>

    <h2 class="card-h">Данные</h2>
    <div class="card">
      <div class="row"><span class="lbl">Резервная копия<small>Отметки, закладки, заметки, прогресс Хифза</small></span><button class="btn ghost" id="s-export" style="min-height:40px;padding:0 14px">${icon('download')} Скачать</button></div>
      <div class="row"><span class="lbl">Восстановить из копии</span><button class="btn ghost" id="s-import" style="min-height:40px;padding:0 14px">${icon('upload')} Выбрать файл</button><input type="file" id="s-file" accept="application/json,.json" hidden></div>
      <div class="row"><span class="lbl">Сбросить всё<small>Удалит данные только из этого браузера</small></span><button class="btn ghost danger" id="s-reset" style="min-height:40px;padding:0 14px">Сбросить</button></div>
    </div>
    <p class="about">«Свет» · версия ${APP_VERSION}<br>Коран, хадисы, азкары, имена Аллаха — из встроенных JSON-файлов.<br>Аудио: everyayah.com · таджвид: alquran.cloud · тафсир Ибн Касира: spa5k/tafsir_api.<br>Дата хиджры — табличная, может отличаться от объявленной по луне на 1–2 дня.</p>`;

  const q = (sel) => $(sel, view);
  $$('#theme button', view).forEach((b) => { b.onclick = () => { setSettings({ theme: b.dataset.v }); $$('#theme button', view).forEach((x) => x.setAttribute('aria-pressed', x === b)); }; });
  q('#city').onchange = (e) => {
    const c = CITIES.find(([n]) => n === e.target.value);
    if (!c) return;
    setSettings({ loc: { name: c[0], lat: c[1], lon: c[2], tz: c[3], chosen: true } });
    q('#loc-sub').textContent = `${c[1].toFixed(3)}, ${c[2].toFixed(3)}`;
    rescheduleNotifications();
    toast('Город изменён');
  };
  q('#geo').onclick = async () => { if (await detectLocation()) renderSettings(view); };
  q('#method').onchange = (e) => { setSettings({ method: e.target.value }); rescheduleNotifications(); toast('Метод расчёта изменён'); };
  q('#reciter').onchange = (e) => setSettings({ reciter: e.target.value });
  q('#s-read').onclick = () => openReadSettings(() => {});
  q('#s-alarm').onclick = () => openAlarmSheet();
  q('#s-name').onclick = async () => { const v = await promptDialog('Имя', { value: getSettings().userName, placeholder: 'Как к вам обращаться?' }); if (v !== null) { setSettings({ userName: v.trim() }); renderSettings(view); } };
  q('#s-mail').onclick = async () => { const v = await promptDialog('Почта', { value: getSettings().userEmail, placeholder: 'you@example.com' }); if (v !== null) { setSettings({ userEmail: v.trim() }); renderSettings(view); } };
  bindSwitches(view, async (id, on, sw) => {
    if (id === 'sw-hanafi') { setSettings({ asrHanafi: on }); rescheduleNotifications(); }
    if (id === 'sw-notify') {
      if (on && !(await askPermission())) { sw.setAttribute('aria-checked', 'false'); return; }
      setSettings({ notify: on }); rescheduleNotifications();
    }
  });
  q('#s-export').onclick = () => {
    const blob = new Blob([JSON.stringify(exportAll(), null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = Object.assign(document.createElement('a'), { href: url, download: `svet-backup-${dayKey()}.json` });
    document.body.append(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 2000);
    toast('Резервная копия сохранена');
  };
  q('#s-import').onclick = () => q('#s-file').click();
  q('#s-file').onchange = async (e) => {
    const f = e.target.files[0];
    if (!f) return;
    try {
      importAll(JSON.parse(await f.text()));
      applyReadingVars();
      toast('Данные восстановлены');
      renderSettings(view);
    } catch (err) { toast(err.message || 'Не удалось прочитать файл'); }
  };
  q('#s-reset').onclick = async () => {
    if (await confirmDialog('Сбросить все данные?', 'Закладки, заметки, прогресс Хифза, отметки и настройки будут удалены из этого браузера. Это нельзя отменить.', 'Сбросить', true)) {
      resetAll(); applyReadingVars(); rescheduleNotifications();
      toast('Данные сброшены');
      renderSettings(view);
    }
  };
  return () => { view.onclick = null; };
}

return { APP_VERSION, detectLocation, openAlarmSheet, renderSettings };
})();

/* ── screens/home.js ── */
const __m_screens_home = (() => {
const { icon, esc, $, toast, pad2 } = __m_core_ui;
const { getSettings, setSettings, getPrayed, togglePrayed, getLastRead } = __m_core_store;
const { dayKey } = __m_core_time;
const { computeDay, todayIn, shiftDate, toHijri } = __m_core_prayer;
const { PRAYER_EVENTS } = __m_core_meta;
const { getQuran } = __m_core_data;
const { rescheduleNotifications } = __m_core_notify;
const { openAlarmSheet } = __m_screens_settings;

const TILES = [
  { ru: 'Коран', icon: 'quran', href: '#/quran' },
  { ru: 'Хифз', icon: 'hifz', href: '#/hifz' },
  { ru: 'Азкары', icon: 'azkar', href: '#/azkar' },
  { ru: '99 имён', icon: 'names', href: '#/names' },
  { ru: 'Трекер', icon: 'tracker', href: '#/tracker' },
  { ru: 'Кибла', icon: 'qibla', href: '#/qibla' },
];
const MOSQUE = `<svg class="hero-mosque" viewBox="0 0 200 100" fill="currentColor" aria-hidden="true">
  <path d="M0 100v-8h200v8z"/><path d="M60 92V72C60 44 80 30 100 20c20 10 40 24 40 52v20z"/>
  <path d="M99 20V8h2v12z"/><circle cx="100" cy="6" r="3.5"/>
  <path d="M36 92V82a14 14 0 0 1 28 0v10zM136 92V82a14 14 0 0 1 28 0v10z"/>
  <path d="M16 92V38l6-14 6 14v54zM172 92V38l6-14 6 14v54z"/><circle cx="22" cy="20" r="2"/><circle cx="178" cy="20" r="2"/></svg>`;

function fmtCount(sec) {
  const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = sec % 60;
  if (h) return `через ${h} ч ${m} мин`;
  if (m) return `через ${m} мин ${pad2(s)} с`;
  return `через ${s} с`;
}

/** Расписание на сегодня и завтра для выбранного в настройках места */
function scheduleFor(offsetDays = 0) {
  const s = getSettings();
  const d = shiftDate(todayIn(s.loc.tz), offsetDays);
  return { date: d, ...computeDay(d, s.loc, s.method, s.asrHanafi) };
}

function nextEvent(today, tomorrow, now) {
  for (const e of PRAYER_EVENTS) {
    const ms = today.ms[e.key];
    if (ms && ms > now) return { ...e, ms, text: today.text[e.key], tomorrow: false };
  }
  return { key: 'fajr', ru: 'Фаджр', ms: tomorrow.ms.fajr, text: tomorrow.text.fajr, tomorrow: true };
}

function renderHome(view) {
  const s = getSettings();
  view.innerHTML = `
    <header class="topbar">
      <div class="brand"><svg class="brand-mark" viewBox="0 0 32 32" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"><rect x="7" y="7" width="18" height="18"/><rect x="7" y="7" width="18" height="18" transform="rotate(45 16 16)"/></g><circle cx="16" cy="16" r="2.6" fill="currentColor"/></svg>Свет</div>
      <button class="icon-btn" id="theme-btn" aria-label="Сменить тему"></button>
    </header>
    <div id="hero"></div>
    <nav class="grid" aria-label="Разделы">
      ${TILES.map((t) => `<a class="tile" href="${t.href}"><span class="tile-ico">${icon(t.icon)}</span>${esc(t.ru)}</a>`).join('')}
    </nav>
    <div id="resume"></div>`;
  setupThemeBtn($('#theme-btn', view));
  renderResume($('#resume', view));

  const hero = $('#hero', view);
  let today = scheduleFor(0), tomorrow = scheduleFor(1);
  let dateKey = JSON.stringify(today.date);
  let ev = null;

  const draw = () => {
    ev = nextEvent(today, tomorrow, Date.now());
    hero.innerHTML = heroHTML(today, ev, s.loc.tz);
  };
  draw();
  rescheduleNotifications();

  hero.addEventListener('click', (e) => {
    const b = e.target.closest('button[data-p]');
    if (b) {
      const on = togglePrayed(dayKey(), b.dataset.p);
      b.classList.toggle('done', on);
      b.setAttribute('aria-pressed', on);
      if (on) toast(`${b.dataset.ru} отмечен`);
      return;
    }
    if (e.target.closest('#alarm-btn')) openAlarmSheet(() => rescheduleNotifications());
  });

  const timer = setInterval(() => {
    const nowDate = todayIn(s.loc.tz);
    if (JSON.stringify(nowDate) !== dateKey) {
      today = scheduleFor(0); tomorrow = scheduleFor(1); dateKey = JSON.stringify(today.date);
      draw(); return;
    }
    const cur = nextEvent(today, tomorrow, Date.now());
    if (cur.key !== ev.key || cur.tomorrow !== ev.tomorrow) { draw(); return; }
    const c = $('#count', hero);
    if (c) c.textContent = fmtCount(Math.max(0, Math.round((cur.ms - Date.now()) / 1000)));
  }, 1000);
  return () => clearInterval(timer);
}

function heroHTML(d, ev, tz) {
  const s = getSettings();
  const prayed = getPrayed(dayKey());
  const now = new Date();
  const dt = new Intl.DateTimeFormat('ru-RU', { weekday: 'long', day: 'numeric', month: 'long', timeZone: tz }).format(now);
  const hijri = toHijri(d.date);
  const secs = Math.max(0, Math.round((ev.ms - Date.now()) / 1000));
  return `<section class="hero" aria-label="Время намаза">
    ${MOSQUE}
    <div class="hero-top">
      <div class="hero-loc">${icon('pin')}${esc(s.loc.name)}</div>
      <button class="hero-bell" id="alarm-btn" aria-label="Умный будильник: Фаджр, Тахаджуд, Сухур">${icon('bell')}</button>
    </div>
    <a class="hero-date" href="#/schedule" aria-label="Расписание намаза на месяц">${esc(dt)} · ${esc(hijri.text)} ${icon('forward')}</a>
    <div class="hero-main">
      <p class="eyebrow">${ev.key === 'sunrise' ? 'Восход солнца' : ev.tomorrow ? 'Следующий намаз · завтра' : 'Следующий намаз'}</p>
      <div class="hero-row"><h1 class="hero-name">${esc(ev.ru)}</h1><div class="hero-time">${esc(ev.text)}</div></div>
      <span class="hero-count" id="count">${fmtCount(secs)}</span>
    </div>
    <div class="times">
      ${PRAYER_EVENTS.map((e) => {
    const active = !ev.tomorrow ? e.key === ev.key : e.key === 'fajr';
    const t = d.text[e.key] || '—';
    if (e.key === 'sunrise') return `<div class="t sun ${active ? 'active' : ''}"><span class="t-name">${e.ru}</span><span class="t-time">${t}</span><span class="t-mark">${icon('sunrise')}</span></div>`;
    const done = !!prayed[e.key];
    return `<button class="t ${done ? 'done' : ''} ${active ? 'active' : ''}" data-p="${e.key}" data-ru="${e.ru}" aria-pressed="${done}" aria-label="${e.ru} ${t}: отметить как совершённый"><span class="t-name">${e.ru}</span><span class="t-time">${t}</span><span class="t-mark">${icon('check')}</span></button>`;
  }).join('')}
    </div>
    ${d.note ? `<p class="hero-note">${esc(d.note)}</p>` : ''}
    ${s.loc.chosen ? '' : '<p class="hero-note">Показано время для Москвы. <a class="hero-link" href="#/settings">Выберите свой город</a></p>'}
  </section>`;
}

async function renderResume(el) {
  const lr = getLastRead();
  if (!lr) return;
  try {
    const surahs = await getQuran();
    const s = surahs[lr.s - 1];
    if (!s) return;
    el.innerHTML = `<a class="resume" href="#/quran/${lr.s}/${lr.a}">${icon('bookmark')}<div><small>Продолжить чтение</small><b>${esc(s.ru)}, аят ${lr.a}</b></div><span class="go">${icon('forward')}</span></a>`;
  } catch { /* данные недоступны — блок просто не показываем */ }
}

function setupThemeBtn(btn) {
  const dark = () => document.documentElement.dataset.theme === 'dark' ||
    (!document.documentElement.dataset.theme && matchMedia('(prefers-color-scheme: dark)').matches);
  const paint = () => { btn.innerHTML = icon(dark() ? 'sun' : 'moon'); };
  paint();
  btn.onclick = () => { setSettings({ theme: dark() ? 'light' : 'dark' }); paint(); };
}

return { scheduleFor, renderHome, setupThemeBtn };
})();

/* ── screens/azkar.js ── */
const __m_screens_azkar = (() => {
const { icon, esc, $, $$, toast, progressBar, emptyState } = __m_core_ui;
const { getAzkarToday, toggleAzkar, bumpAzkar } = __m_core_store;
const { getAzkar, getQuran } = __m_core_data;
const { AZKAR_CATS } = __m_core_meta;
const { arDigits } = __m_core_ui;
const { plural } = __m_core_ui;

let cat = 'morning';

/** Азкар-«чтение суры» подтягивает текст из Корана (в исходном JSON там только подсказка) */
function resolveRef(item, surahs) {
  if (!item.ref || !surahs) return item;
  const s = surahs[item.ref.surah - 1];
  if (!s) return item;
  const parts = [], ru = [];
  for (let a = item.ref.from; a <= item.ref.to; a++) {
    parts.push(`${s.ayahs[a - 1][0]} ﴿${arDigits(a)}﴾`);
    ru.push(s.ayahs[a - 1][1]);
  }
  return { ...item, textAr: parts.join(' '), translationRu: ru.join(' '), refLabel: `${s.ru}, ${item.ref.from === item.ref.to ? 'аят ' + item.ref.from : 'аяты ' + item.ref.from + '–' + item.ref.to}` };
}

async function renderAzkar(view) {
  view.innerHTML = `<h1 class="page-title">Азкары</h1>
    <div class="seg" role="tablist" aria-label="Время">${AZKAR_CATS.map((c) => `<button role="tab" data-c="${c.id}" aria-selected="${cat === c.id}">${c.ru}</button>`).join('')}</div>
    <div id="zk"><div class="skel" style="height:300px;margin-top:16px"></div></div>`;
  $$('[data-c]', view).forEach((b) => { b.onclick = () => { cat = b.dataset.c; renderAzkar(view); }; });
  const host = $('#zk', view);
  let data, surahs = null;
  try { data = await getAzkar(); } catch { host.innerHTML = emptyState('Не удалось загрузить азкары', 'Обновите страницу.'); return; }
  try { surahs = await getQuran(); } catch { /* ссылки на суры покажутся без текста */ }

  const total = AZKAR_CATS.reduce((t, c) => t + (data[c.id]?.length || 0), 0);
  const draw = () => {
    const today = getAzkarToday();
    const doneCount = AZKAR_CATS.reduce((t, c) => t + (data[c.id] || []).filter((i) => today.done[`${c.id}_${i.id}`]).length, 0);
    const list = (data[cat] || []).map((raw) => resolveRef(raw, surahs));
    host.innerHTML = `
      <div class="card zk-progress"><div><b>Мой прогресс</b><small>Сегодня выполнено ${doneCount} из ${total} ${plural(total, 'азкара', 'азкаров', 'азкаров')}</small></div>${progressBar(total ? doneCount / total : 0, 'Прогресс азкаров за день')}</div>
      ${list.length ? list.map((it) => {
    const key = `${cat}_${it.id}`, done = !!today.done[key], n = today.counts[key] || 0;
    return `<article class="zk ${done ? 'done' : ''}" data-k="${key}" data-max="${it.count}">
        <header><button class="zk-chk" data-x="chk" aria-pressed="${done}" aria-label="${done ? 'Снять отметку' : 'Отметить выполненным'}: ${esc(it.title)}">${icon(done ? 'checkc' : 'circle')}</button>
          <h3>${esc(it.title)}</h3><span class="cnt">${it.count} ${plural(it.count, 'раз', 'раза', 'раз')}</span></header>
        ${it.refLabel ? `<small class="muted ref">${esc(it.refLabel)}</small>` : ''}
        <div class="a-ar" lang="ar" dir="rtl">${esc(it.textAr)}</div>
        ${it.translit ? `<p class="zk-tr">${esc(it.translit)}</p>` : ''}
        ${it.translationRu ? `<p class="a-ru">${esc(it.translationRu)}</p>` : ''}
        ${it.virtue ? `<p class="zk-virtue">${esc(it.virtue)}</p>` : ''}
        ${it.count > 1 && !done ? `<button class="tasbih" data-x="bump" aria-label="Отсчитать: ${esc(it.title)}"><b>${n}</b> / ${it.count}<small>Нажимайте после каждого повторения</small></button>` : ''}
      </article>`;
  }).join('') : emptyState('Данные не найдены', '')}`;
  };
  draw();
  view.onclick = (e) => {
    const x = e.target.closest('[data-x]');
    if (!x) return;
    const card = x.closest('[data-k]');
    const key = card.dataset.k;
    if (x.dataset.x === 'chk') { toggleAzkar(key); } else {
      const r = bumpAzkar(key, +card.dataset.max);
      if (r.done) toast('Азкар выполнен');
    }
    const y = window.scrollY;
    draw();
    window.scrollTo(0, y);
  };
  return () => { view.onclick = null; };
}

return { renderAzkar };
})();

/* ── screens/hadith.js ── */
const __m_screens_hadith = (() => {
const { icon, esc, $, $$, toast, copyText, hl, emptyState, plural } = __m_core_ui;
const { getHadiths } = __m_core_data;
const { HADITH_TAGS, HADITH_BOOKS } = __m_core_meta;

let book = 'bukhari', tag = 'Все', query = '';

/** param — «bookId:number» из ссылки в тафсире: открываем нужный хадис */
async function renderHadith(view, param) {
  let focus = null;
  if (param) {
    const [b, n] = decodeURIComponent(param).split(':');
    if (HADITH_BOOKS.some((x) => x.id === b)) { book = b; tag = 'Все'; query = ''; focus = `${b}-${n}`; }
  }
  view.innerHTML = `<h1 class="page-title">Хадисы</h1><div id="hbox"><div class="skel" style="height:300px;margin-top:16px"></div></div>`;
  const box = $('#hbox', view);
  let all;
  try { all = await getHadiths(); } catch { box.innerHTML = emptyState('Не удалось загрузить хадисы', 'Обновите страницу.'); return; }
  const open = new Set();   // раскрытые блоки: "bukhari-1:isnad"

  box.innerHTML = `
    <div class="book-row">${HADITH_BOOKS.map((b) => {
    const cnt = all.filter((h) => h.bookId === b.id).length;
    return `<button class="book" data-b="${b.id}" aria-pressed="${book === b.id}"><b>${esc(b.ru)}</b><small>${cnt} ${plural(cnt, 'хадис', 'хадиса', 'хадисов')}</small></button>`;
  }).join('')}</div>
    <div class="search" style="margin-top:12px">${icon('search')}<input id="hq" type="search" placeholder="Слово или фраза (рус./араб.)" value="${esc(query)}" autocomplete="off" aria-label="Поиск по хадисам"></div>
    <div class="tag-row" role="group" aria-label="Тема">${HADITH_TAGS.map((t) => `<button class="tag" data-t="${esc(t)}" aria-pressed="${tag === t}">${esc(t)}</button>`).join('')}</div>
    <div id="hlist"></div>`;
  const list = $('#hlist', box);

  const paint = () => {
    const q = query.trim().toLowerCase();
    const items = all.filter((h) => {
      const okBook = q ? true : h.bookId === book;       // при активном поиске ищем по всем книгам
      const okTag = tag === 'Все' || h.tag.toLowerCase() === tag.toLowerCase();
      const okQ = !q || h.title.toLowerCase().includes(q) || h.translationRu.toLowerCase().includes(q) || h.textAr.includes(query.trim());
      return okBook && okTag && okQ;
    });
    if (!items.length) { list.innerHTML = emptyState('Ничего не найдено', 'Измените запрос или тему.'); return; }
    list.innerHTML = (q ? `<p class="page-sub" style="margin:10px 2px">Найдено: ${items.length} · поиск идёт по обеим книгам</p>` : '') + items.map((h) => {
      const id = `${h.bookId}-${h.number}`;
      const isn = open.has(id + ':isnad'), com = open.has(id + ':com');
      return `<article class="hd" id="h-${id}" data-id="${id}">
        <div class="hd-top"><h3>${hl(h.title, q)}</h3><span class="chip">${esc(h.tag)}</span></div>
        <div class="a-ar" lang="ar" dir="rtl">${esc(h.textAr)}</div>
        <p class="a-ru">${hl(h.translationRu, q)}</p>
        <p class="hd-src">${esc(h.source)} · ${esc(h.grade)}</p>
        <div class="hd-acts">
          ${h.isnad?.length ? `<button class="chip-btn" data-x="isnad" aria-expanded="${isn}">Иснад</button>` : ''}
          ${h.commentary ? `<button class="chip-btn" data-x="com" aria-expanded="${com}">Комментарий</button>` : ''}
          <button class="chip-btn" data-x="copy">${icon('copy')} Копировать</button></div>
        ${isn ? `<ol class="isnad">${h.isnad.map((t) => `<li><b>${esc(t.name)}</b><small>${esc(t.gen)}</small></li>`).join('')}</ol>` : ''}
        ${com ? `<p class="hd-com">${esc(h.commentary)}</p>` : ''}
      </article>`;
    }).join('');
  };
  paint();

  let t;
  $('#hq', box).oninput = (e) => { query = e.target.value; clearTimeout(t); t = setTimeout(paint, 160); };
  box.onclick = async (e) => {
    const b = e.target.closest('[data-b]');
    if (b) { book = b.dataset.b; query = ''; $('#hq', box).value = ''; $$('[data-b]', box).forEach((x) => x.setAttribute('aria-pressed', x === b)); return paint(); }
    const tg = e.target.closest('[data-t]');
    if (tg) { tag = tg.dataset.t; $$('[data-t]', box).forEach((x) => x.setAttribute('aria-pressed', x === tg)); return paint(); }
    const x = e.target.closest('[data-x]');
    if (!x) return;
    const id = x.closest('[data-id]').dataset.id, h = all.find((v) => `${v.bookId}-${v.number}` === id);
    if (x.dataset.x === 'copy') {
      return toast((await copyText(`${h.title}\n\n${h.textAr}\n\n${h.translationRu}\n\n${h.source}`)) ? 'Хадис скопирован' : 'Не удалось скопировать');
    }
    const k = id + ':' + x.dataset.x;
    open.has(k) ? open.delete(k) : open.add(k);
    const y = window.scrollY; paint(); window.scrollTo(0, y);
  };
  if (focus) {
    const el = $('#h-' + focus, box);
    if (el) requestAnimationFrame(() => { el.scrollIntoView({ block: 'start' }); el.classList.add('flash'); });
  }
  return () => { box.onclick = null; };
}

return { renderHadith };
})();

/* ── screens/names.js ── */
const __m_screens_names = (() => {
const { icon, esc, $, toast, openSheet, subbar, emptyState, clamp, progressBar } = __m_core_ui;
const { getNames } = __m_core_data;
const { getNamesViewed, markNameViewed, getNamesFav, toggleNameFav } = __m_core_store;

let idx = 0;

async function renderNames(view, param) {
  view.innerHTML = '<div class="skel" style="height:400px;margin-top:70px"></div>';
  let names;
  try { names = await getNames(); } catch { view.innerHTML = emptyState('Не удалось загрузить имена', 'Обновите страницу.'); return; }
  if (param && +param >= 1 && +param <= names.length) idx = +param - 1;
  idx = clamp(idx, 0, names.length - 1);

  const draw = () => {
    const n = names[idx];
    markNameViewed(n.number);
    const fav = getNamesFav().has(n.number), viewed = getNamesViewed().size;
    view.innerHTML = `${subbar('99 имён Аллаха', '#/', `<button class="icon-btn" id="n-list" aria-label="Все имена">${icon('list')}</button><button class="icon-btn" id="n-favs" aria-label="Избранные имена">${icon('heart')}</button>`)}
      <div class="name-wrap" id="swipe">
        <button class="btn ${fav ? '' : 'ghost'}" id="n-fav" style="width:100%">${icon('heart')} ${fav ? 'В избранном' : 'Добавить в избранное'}</button>
        <div class="name-hero"><div class="name-ar" lang="ar">${esc(n.arabic)}</div></div>
        <h1 class="name-tr">${esc(n.transliteration)}</h1>
        <p class="name-meaning">${esc(n.translation)}</p>
        <div class="card name-interp"><h3 class="sub-h">Значение</h3><p>${esc(n.interpretation)}</p></div>
        <div class="pager"><button class="icon-btn" id="n-prev" ${idx === 0 ? 'disabled' : ''} aria-label="Предыдущее имя">${icon('back')}</button>
          <b>${idx + 1} / ${names.length}</b>
          <button class="icon-btn" id="n-next" ${idx === names.length - 1 ? 'disabled' : ''} aria-label="Следующее имя">${icon('forward')}</button></div>
        <div class="seen">${progressBar(viewed / names.length, 'Изучено имён')}<small>Изучено имён: ${viewed} из ${names.length}</small></div>
      </div>`;
  };
  draw();
  const go = (d) => { const j = idx + d; if (j < 0 || j >= names.length) return; idx = j; draw(); window.scrollTo(0, 0); };

  const listSheet = (title, items, empty) => openSheet(title, `
    ${items === null ? '<div class="search" style="margin-bottom:10px">' + icon('search') + '<input id="nq" type="search" placeholder="Имя или значение" autocomplete="off"></div>' : ''}
    <div id="nl"></div>`, (root, close) => {
    const nl = $('#nl', root), q = $('#nq', root);
    const paint = () => {
      const v = (q?.value || '').trim().toLowerCase();
      const src = items === null ? names : names.filter((x) => getNamesFav().has(x.number));
      const rows = src.filter((x) => !v || x.transliteration.toLowerCase().includes(v) || x.translation.toLowerCase().includes(v) || String(x.number) === v);
      const viewed = getNamesViewed();
      nl.innerHTML = rows.length ? rows.map((x) => `<button class="nrow ${viewed.has(x.number) ? 'seen' : ''}" data-i="${x.number - 1}"><span class="nr-n">${x.number}</span><span class="nr-ar" lang="ar">${esc(x.arabic)}</span><span class="nr-t"><b>${esc(x.transliteration)}</b><small>${esc(x.translation)}</small></span></button>`).join('')
        : `<p class="muted-p" style="padding:16px 0">${empty}</p>`;
    };
    paint();
    q?.addEventListener('input', paint);
    root.addEventListener('click', (e) => {
      const b = e.target.closest('[data-i]');
      if (b) { idx = +b.dataset.i; close(); draw(); window.scrollTo(0, 0); }
    });
  });

  view.onclick = (e) => {
    if (e.target.closest('#n-prev')) return go(-1);
    if (e.target.closest('#n-next')) return go(1);
    if (e.target.closest('#n-fav')) {
      const on = toggleNameFav(names[idx].number);
      toast(on ? 'Добавлено в избранное' : 'Убрано из избранного');
      return draw();
    }
    if (e.target.closest('#n-list')) return listSheet('Все имена', null, '');
    if (e.target.closest('#n-favs')) return listSheet('Избранные имена', [], 'Пока пусто — нажмите «Добавить в избранное» на понравившемся имени');
  };

  // Свайп влево/вправо
  let x0 = null, y0 = null;
  view.ontouchstart = (e) => { x0 = e.touches[0].clientX; y0 = e.touches[0].clientY; };
  view.ontouchend = (e) => {
    if (x0 == null) return;
    const dx = e.changedTouches[0].clientX - x0, dy = e.changedTouches[0].clientY - y0;
    x0 = null;
    if (Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy) * 1.5) go(dx < 0 ? 1 : -1);
  };
  return () => { view.onclick = null; view.ontouchstart = null; view.ontouchend = null; };
}

return { renderNames };
})();

/* ── screens/tracker.js ── */
const __m_screens_tracker = (() => {
const { icon, esc, $, toast, subbar, progressBar, ringSvg, confirmDialog, plural, clamp } = __m_core_ui;
const { getPrayed, togglePrayed, getKhatm, setKhatm, getAzkarToday, getMemorized, getNamesViewed } = __m_core_store;
const { getAzkar } = __m_core_data;
const { dayKey, addDays, startOfDay, diffDays, parseDay, fmtDMY } = __m_core_time;
const { OBLIGATORY, QUOTES, TOTAL_PAGES, AZKAR_CATS } = __m_core_meta;
const { scheduleFor } = __m_screens_home;

/* ═════ Трекер ═════ */
async function renderTracker(view) {
  const today = dayKey();
  let azkarTotal = 0;
  try { const z = await getAzkar(); azkarTotal = AZKAR_CATS.reduce((t, c) => t + (z[c.id]?.length || 0), 0); } catch { /* без данных азкаров */ }

  const draw = () => {
    const prayed = getPrayed(today), cnt = OBLIGATORY.filter((p) => prayed[p.key]).length;
    const sch = scheduleFor(0), now = Date.now();
    const nxt = OBLIGATORY.find((p) => sch.ms[p.key] && sch.ms[p.key] > now);
    const k = getKhatm(), az = Object.keys(getAzkarToday().done).length, mem = getMemorized().size, nm = getNamesViewed().size;
    const quote = QUOTES[Math.floor((startOfDay() - new Date(2024, 0, 1)) / 86400000) % QUOTES.length];
    // последние 7 дней — из истории отметок
    const hist = Array.from({ length: 7 }, (_, i) => {
      const d = addDays(startOfDay(), i - 6), p = getPrayed(dayKey(d));
      return { d, n: OBLIGATORY.filter((o) => p[o.key]).length };
    });
    const cats = [
      { ic: 'quran', t: 'Коран', v: k.active ? `${k.page} / ${TOTAL_PAGES}` : 'план не задан', f: k.active ? k.page / TOTAL_PAGES : 0, href: '#/tracker/khatm' },
      { ic: 'azkar', t: 'Азкары', v: `${az} / ${azkarTotal}`, f: azkarTotal ? az / azkarTotal : 0, href: '#/azkar' },
      { ic: 'hifz', t: 'Хифз', v: `${mem} / 114 сур`, f: mem / 114, href: '#/hifz' },
      { ic: 'names', t: '99 имён', v: `${nm} / 99`, f: nm / 99, href: '#/names' },
    ];
    view.innerHTML = `${subbar('Трекер', '#/')}
      <section class="card trk-pray">
        <div class="trk-head"><span class="trk-ico">${icon('mosque')}</span><div><b>Сегодня ${cnt} / 5 намазов</b><small>${nxt ? 'Следующий: ' + nxt.ru : 'Следующий: Фаджр (завтра)'}</small></div></div>
        <div class="trk-prayers">${OBLIGATORY.map((p) => `<button class="trk-p ${prayed[p.key] ? 'done' : ''}" data-p="${p.key}" aria-pressed="${!!prayed[p.key]}" aria-label="${p.ru}: отметить"><span>${icon('check')}</span>${p.ru}</button>`).join('')}</div>
      </section>
      <div class="trk-grid">${cats.map((c) => `<a class="trk-cat" href="${c.href}"><div class="trk-cat-h">${icon(c.ic)}<b>${c.t}</b></div><small>${esc(c.v)}</small>${progressBar(c.f, c.t)}</a>`).join('')}</div>
      <h2 class="card-h">Намазы за 7 дней</h2>
      <section class="card week"><div class="week-bars">${hist.map((h) => `<div class="wk ${diffDays(h.d, startOfDay()) === 0 ? 'today' : ''}"><i style="height:${(h.n / 5) * 100}%"></i><b>${h.n}</b><small>${['Вс', 'Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб'][h.d.getDay()]}</small></div>`).join('')}</div></section>
      <p class="quote">${esc(quote)}</p>`;
  };
  draw();
  view.onclick = (e) => {
    const b = e.target.closest('[data-p]');
    if (!b) return;
    togglePrayed(today, b.dataset.p);
    draw();
  };
  return () => { view.onclick = null; };
}

/* ═════ Хатм-план ═════ */
const effPerDay = (k) => {
  const remaining = clamp(TOTAL_PAGES - k.page + 1, 0, TOTAL_PAGES);
  if (k.mode === 0 || !k.target) return k.pagesPerDay;
  const left = diffDays(startOfDay(), parseDay(k.target));
  if (left <= 0) return remaining;
  return clamp(Math.ceil(remaining / left), 1, TOTAL_PAGES);
};
const finishDate = (k) => {
  if (k.mode === 1 && k.target) return parseDay(k.target);
  const remaining = clamp(TOTAL_PAGES - k.page + 1, 0, TOTAL_PAGES);
  return addDays(startOfDay(), Math.ceil(remaining / k.pagesPerDay));
};

function renderKhatm(view) {
  let setup = { mode: 0, pages: 5, target: dayKey(addDays(startOfDay(), 30)) };
  const draw = () => {
    const k = getKhatm();
    if (!k.active) return drawSetup();
    const remaining = clamp(TOTAL_PAGES - k.page + 1, 0, TOTAL_PAGES);
    const frac = clamp((k.page - 1) / TOTAL_PAGES, 0, 1), fd = finishDate(k);
    view.innerHTML = `${subbar('Хатм-план', '#/tracker')}
      <section class="khatm-card">
        <div class="khatm-top">${ringSvg(frac, Math.round(frac * 100) + '%')}<div><b>Осталось ${remaining} ${plural(remaining, 'страница', 'страницы', 'страниц')}</b>
          <small>Читай ${effPerDay(k)} стр/день, чтобы закончить к ${fmtDMY(fd)}</small></div></div>
        <div class="khatm-page"><label for="kp">Сейчас я на странице:</label><input id="kp" class="field" type="number" min="1" max="${TOTAL_PAGES}" value="${k.page}" inputmode="numeric"><button class="btn" id="k-save">${icon('check')} Сохранить</button></div>
        <p class="khatm-note">План сам пересчитает темп, если ты отстал или прочитал больше</p>
      </section>
      <button class="btn ghost" id="k-edit" style="margin-top:16px">${icon('refresh')} Изменить план</button>`;
  };
  const drawSetup = () => {
    const days = Math.ceil(TOTAL_PAGES / setup.pages), fd = addDays(startOfDay(), days);
    const left = Math.max(1, diffDays(startOfDay(), parseDay(setup.target)));
    view.innerHTML = `${subbar('Хатм-план', '#/tracker')}
      <p class="page-sub" style="margin:14px 2px">Выберите, как планировать чтение всего Корана целиком (${TOTAL_PAGES} страниц Мединского мусхафа):</p>
      <section class="card" style="padding:16px">
        <div class="seg"><button data-m="0" aria-pressed="${setup.mode === 0}">Страниц в день</button><button data-m="1" aria-pressed="${setup.mode === 1}">К дате</button></div>
        ${setup.mode === 0 ? `
          <div class="row stack"><label for="kpd">Страниц в день: <b id="kpd-v">${setup.pages}</b></label><input class="range wide" id="kpd" type="range" min="1" max="30" value="${setup.pages}"></div>
          <p class="muted-p small" id="k-hint">Ты закончишь весь Коран примерно через ${days} ${plural(days, 'день', 'дня', 'дней')} — к ${fmtDMY(fd)}</p>`
    : `<div class="row stack"><label for="kd">Дата завершения</label><input class="field wide" id="kd" type="date" min="${dayKey(addDays(startOfDay(), 1))}" value="${setup.target}"></div>
          <p class="muted-p small" id="k-hint">Понадобится читать примерно ${Math.ceil(TOTAL_PAGES / left)} стр. в день</p>`}
        <button class="btn" id="k-start" style="width:100%;margin-top:12px">Начать план</button>
      </section>`;
  };
  draw();
  view.onclick = async (e) => {
    const m = e.target.closest('[data-m]');
    if (m) { setup.mode = +m.dataset.m; return drawSetup(); }
    if (e.target.closest('#k-start')) {
      const k = getKhatm();
      if (setup.mode === 1 && diffDays(startOfDay(), parseDay(setup.target)) < 1) return toast('Выберите дату в будущем');
      setKhatm({ active: true, mode: setup.mode, pagesPerDay: setup.pages, target: setup.mode === 1 ? setup.target : null, start: dayKey(), page: k.page || 1 });
      return draw();
    }
    if (e.target.closest('#k-save')) {
      const v = Math.round(+$('#kp', view).value);
      if (!v || v < 1 || v > TOTAL_PAGES) return toast(`Введите страницу от 1 до ${TOTAL_PAGES}`);
      setKhatm({ ...getKhatm(), page: v });
      toast('Страница сохранена');
      return draw();
    }
    if (e.target.closest('#k-edit')) {
      if (await confirmDialog('Изменить план?', 'Текущая страница сохранится — вы выберете новый темп или дату.', 'Изменить')) { setKhatm({ ...getKhatm(), active: false }); draw(); }
    }
  };
  view.oninput = (e) => {
    if (e.target.id === 'kpd') {
      setup.pages = +e.target.value;
      const days = Math.ceil(TOTAL_PAGES / setup.pages);
      $('#kpd-v', view).textContent = setup.pages;
      $('#k-hint', view).textContent = `Ты закончишь весь Коран примерно через ${days} ${plural(days, 'день', 'дня', 'дней')} — к ${fmtDMY(addDays(startOfDay(), days))}`;
    }
    if (e.target.id === 'kd') { setup.target = e.target.value || setup.target; const left = Math.max(1, diffDays(startOfDay(), parseDay(setup.target))); $('#k-hint', view).textContent = `Понадобится читать примерно ${Math.ceil(TOTAL_PAGES / left)} стр. в день`; }
  };
  return () => { view.onclick = null; view.oninput = null; };
}

return { renderTracker, renderKhatm };
})();

/* ── screens/qibla.js ── */
const __m_screens_qibla = (() => {
const { icon, esc, $, toast, subbar } = __m_core_ui;
const { getSettings } = __m_core_store;
const { qiblaBearing, distanceToKaabaKm } = __m_core_prayer;
const { detectLocation } = __m_screens_settings;

let qTab = 'qibla';
const DIRS = ['север', 'северо-восток', 'восток', 'юго-восток', 'юг', 'юго-запад', 'запад', 'северо-запад'];
const cardinal = (deg) => DIRS[Math.round(deg / 45) % 8];

function dialSvg() {
  const ticks = Array.from({ length: 72 }, (_, i) => {
    const a = i * 5, major = a % 90 === 0, mid = a % 30 === 0;
    const r1 = 96, r2 = major ? 80 : mid ? 86 : 90;
    const rad = (a - 90) * Math.PI / 180;
    return `<line x1="${(100 + r1 * Math.cos(rad)).toFixed(1)}" y1="${(100 + r1 * Math.sin(rad)).toFixed(1)}" x2="${(100 + r2 * Math.cos(rad)).toFixed(1)}" y2="${(100 + r2 * Math.sin(rad)).toFixed(1)}" class="${major ? 'tk-m' : 'tk'}"/>`;
  }).join('');
  return `<svg viewBox="0 0 200 200" class="dial-svg" aria-hidden="true"><circle cx="100" cy="100" r="98" class="dial-ring"/>${ticks}
    <text x="100" y="72" class="dial-n">С</text><text x="162" y="104" class="dial-l">В</text><text x="100" y="140" class="dial-l">Ю</text><text x="38" y="104" class="dial-l">З</text></svg>`;
}

function renderQibla(view) {
  const s = getSettings(), { lat, lon, name } = s.loc;
  const bearing = qiblaBearing(lat, lon), dist = Math.round(distanceToKaabaKm(lat, lon));
  let heading = null, off = null;

  const draw = () => {
    const l = getSettings().loc;
    view.innerHTML = `${subbar('Кибла', '#/')}
      <div class="seg" style="margin-top:12px"><button data-q="qibla" aria-pressed="${qTab === 'qibla'}">${icon('qibla')} Кибла</button><button data-q="mosque" aria-pressed="${qTab === 'mosque'}">${icon('mosque')} Мечети рядом</button></div>
      ${qTab === 'qibla' ? `
        <div class="compass" id="compass">
          <div class="dial" id="dial">${dialSvg()}
            <div class="qmark" id="qmark" style="transform:rotate(${bearing}deg)"><span>${icon('mosque')}</span></div></div>
          <div class="pointer" aria-hidden="true"></div>
        </div>
        <p class="q-status" id="q-status" role="status">${bearing.toFixed(0)}° от севера — ${cardinal(bearing)}</p>
        <div class="card q-info">
          <div class="row"><span class="lbl">Местоположение<small>${esc(l.name)}${l.chosen ? '' : ' (по умолчанию)'}</small></span><button class="btn ghost" id="q-geo" style="min-height:40px;padding:0 14px">${icon('pin')} Определить</button></div>
          <div class="row"><span class="lbl">Направление на Каабу</span><b>${bearing.toFixed(1)}°</b></div>
          <div class="row"><span class="lbl">Расстояние до Каабы</span><b>${dist.toLocaleString('ru-RU')} км</b></div>
        </div>
        <button class="btn" id="q-sensor" style="width:100%;margin-top:12px">${icon('qibla')} Включить компас телефона</button>
        <p class="muted-p small" id="q-hint" style="text-align:center;margin-top:8px">Без датчика циферблат неподвижен: север сверху, значок мечети показывает направление на Каабу. Отойдите от металла и магнитов.</p>`
    : `<div class="card" style="padding:18px;margin-top:16px;text-align:center"><span class="big-ico">${icon('mosque')}</span><h3 class="sub-h">Мечети рядом с вами</h3>
        <p class="muted-p">Откроется карта с поиском мечетей возле выбранного места: ${esc(l.name)}.</p>
        <a class="btn" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/${encodeURIComponent('мечеть')}/@${l.lat},${l.lon},14z">${icon('external')} Открыть карту</a></div>`}`;
  };
  draw();

  const setHeading = (h) => {
    heading = (h + 360) % 360;
    const dial = $('#dial', view);
    if (!dial) return;
    dial.style.transform = `rotate(${-heading}deg)`;
    const diff = Math.abs(((bearing - heading + 540) % 360) - 180);
    const ok = diff <= 5;
    const st = $('#q-status', view);
    if (st) { st.textContent = ok ? 'Вы смотрите в сторону Каабы' : `Поверните телефон: до киблы ${Math.round(((bearing - heading + 360) % 360))}° по часовой`; st.classList.toggle('ok', ok); }
    $('#compass', view)?.classList.toggle('ok', ok);
  };
  const onOrient = (e) => {
    let h = null;
    if (typeof e.webkitCompassHeading === 'number') h = e.webkitCompassHeading;
    else if (e.absolute && typeof e.alpha === 'number') h = 360 - e.alpha;
    else if (e.type === 'deviceorientationabsolute' && typeof e.alpha === 'number') h = 360 - e.alpha;
    if (h != null && !Number.isNaN(h)) setHeading(h);
  };
  const startSensor = async () => {
    try {
      const DOE = window.DeviceOrientationEvent;
      if (!DOE) return toast('Датчик ориентации недоступен на этом устройстве');
      if (typeof DOE.requestPermission === 'function') {
        const r = await DOE.requestPermission();
        if (r !== 'granted') return toast('Доступ к датчику не разрешён');
      }
      window.addEventListener('deviceorientationabsolute', onOrient, true);
      window.addEventListener('deviceorientation', onOrient, true);
      off = () => { window.removeEventListener('deviceorientationabsolute', onOrient, true); window.removeEventListener('deviceorientation', onOrient, true); };
      const hint = $('#q-hint', view);
      if (hint) hint.textContent = 'Держите телефон горизонтально. Если стрелка не двигается — датчик недоступен (на компьютере его нет).';
      const b = $('#q-sensor', view); if (b) b.hidden = true;
      setTimeout(() => { if (heading == null) toast('Датчик не отвечает — используйте направление в градусах'); }, 2500);
    } catch { toast('Не удалось включить компас'); }
  };

  view.onclick = async (e) => {
    const q = e.target.closest('[data-q]');
    if (q) { qTab = q.dataset.q; off?.(); off = null; return renderQibla(view); }
    if (e.target.closest('#q-sensor')) return startSensor();
    if (e.target.closest('#q-geo')) { if (await detectLocation()) renderQibla(view); }
  };
  return () => { off?.(); view.onclick = null; };
}

return { renderQibla };
})();

/* ── screens/schedule.js ── */
const __m_screens_schedule = (() => {
const { esc, $, subbar, icon, emptyState } = __m_core_ui;
const { getSettings } = __m_core_store;
const { computeDay, todayIn, toHijri } = __m_core_prayer;
const { MONTHS_NOM, WEEKDAYS_SHORT, HIJRI_MONTHS } = __m_core_meta;

let shift = 0;   // смещение в месяцах от текущего

function renderSchedule(view) {
  const s = getSettings();
  const t = todayIn(s.loc.tz);
  let y = t.y, m = t.m + shift;
  while (m < 1) { m += 12; y--; }
  while (m > 12) { m -= 12; y++; }
  const days = new Date(Date.UTC(y, m, 0)).getUTCDate();
  const rows = [];
  for (let d = 1; d <= days; d++) {
    const r = computeDay({ y, m, d }, s.loc, s.method, s.asrHanafi);
    const wd = (new Date(Date.UTC(y, m - 1, d)).getUTCDay() + 6) % 7;
    const isToday = y === t.y && m === t.m && d === t.d;
    rows.push(`<tr class="${isToday ? 'today' : ''} ${wd === 4 ? 'fri' : ''}"><th scope="row"><b>${d}</b><small>${WEEKDAYS_SHORT[wd]}</small></th>
      <td>${r.text.fajr}</td><td>${r.text.dhuhr}</td><td>${r.text.asr}</td><td>${r.text.maghrib}</td><td>${r.text.isha}</td></tr>`);
  }
  const h1 = toHijri({ y, m, d: 1 }), h2 = toHijri({ y, m, d: days });
  const hijriRange = h1.month === h2.month ? `${HIJRI_MONTHS[h1.month - 1]} ${h1.year}` : `${HIJRI_MONTHS[h1.month - 1]} – ${HIJRI_MONTHS[h2.month - 1]} ${h2.year}`;
  view.innerHTML = `${subbar('Расписание намаза', '#/')}
    <div class="month-nav"><button class="icon-btn" id="m-prev" aria-label="Предыдущий месяц">${icon('back')}</button>
      <div><b>${MONTHS_NOM[m - 1]} ${y}</b><small>${esc(hijriRange)} · ${esc(s.loc.name)}</small></div>
      <button class="icon-btn" id="m-next" aria-label="Следующий месяц">${icon('forward')}</button></div>
    ${days ? `<div class="sched-wrap"><table class="sched"><thead><tr><th scope="col"></th><th scope="col">Фаджр</th><th scope="col">Зухр</th><th scope="col">Аср</th><th scope="col">Магриб</th><th scope="col">Иша</th></tr></thead><tbody>${rows.join('')}</tbody></table></div>` : emptyState('Нет данных', '')}
    <p class="muted-p small" style="margin-top:12px">Метод и мазхаб Асра — в настройках. Дата хиджры табличная и может отличаться от объявленной по луне на 1–2 дня.</p>`;
  $('#m-prev', view).onclick = () => { shift--; renderSchedule(view); };
  $('#m-next', view).onclick = () => { shift++; renderSchedule(view); };
  requestAnimationFrame(() => $('tr.today', view)?.scrollIntoView({ block: 'center' }));
  return () => { shift = 0; };
}

return { renderSchedule };
})();

/* ── main.js ── */
const { icon, $, $$, toast, openSheet, closeSheet, esc } = __m_core_ui;
const { getSettings, onSettings } = __m_core_store;
const { getQuran } = __m_core_data;
const { setAyahCounts, onAudio, getAudio, togglePlay, stopAudio, setSleepTimer } = __m_core_audio;
const { renderHome } = __m_screens_home;
const { renderQuran, renderReader, applyReadingVars } = __m_screens_quran;
const { renderHifz, renderCheck } = __m_screens_hifz;
const { renderAzkar } = __m_screens_azkar;
const { renderHadith } = __m_screens_hadith;
const { renderNames } = __m_screens_names;
const { renderTracker, renderKhatm } = __m_screens_tracker;
const { renderQibla } = __m_screens_qibla;
const { renderSchedule } = __m_screens_schedule;
const { renderSettings } = __m_screens_settings;

const TABS = [
  { id: 'home', ru: 'Главная', icon: 'home', href: '#/' },
  { id: 'quran', ru: 'Коран', icon: 'quran', href: '#/quran' },
  { id: 'azkar', ru: 'Азкары', icon: 'azkar', href: '#/azkar' },
  { id: 'hadith', ru: 'Хадисы', icon: 'hadith', href: '#/hadith' },
  { id: 'settings', ru: 'Настройки', icon: 'settings', href: '#/settings' },
];
const TITLES = { home: 'Свет', quran: 'Коран', azkar: 'Азкары', hadith: 'Хадисы', settings: 'Настройки', hifz: 'Хифз', names: '99 имён', tracker: 'Трекер', qibla: 'Кибла', schedule: 'Расписание' };

const view = $('#view');
let cleanup = null, seq = 0, surahNames = [];

function applyTheme(s = getSettings()) {
  if (s.theme === 'light' || s.theme === 'dark') document.documentElement.dataset.theme = s.theme;
  else document.documentElement.removeAttribute('data-theme');
}
applyTheme(); applyReadingVars();
onSettings((s, patch) => { if ('theme' in patch || !Object.keys(patch).length) applyTheme(s); });

function paintTabs(active) {
  $('#tabbar').innerHTML = TABS.map((t) =>
    `<a class="tab" href="${t.href}" ${t.id === active ? 'aria-current="page"' : ''}>${icon(t.icon)}<span>${t.ru}</span></a>`).join('');
}

const ROUTES = {
  '': { tab: 'home', fn: (p) => renderHome(view, p) },
  quran: { tab: 'quran', fn: (p) => (p[0] ? renderReader(view, +p[0], +p[1] || 0) : renderQuran(view)) },
  hifz: { tab: 'home', fn: (p) => (p[0] === 'check' ? renderCheck(view, +p[1]) : renderHifz(view)) },
  azkar: { tab: 'azkar', fn: () => renderAzkar(view) },
  hadith: { tab: 'hadith', fn: (p) => renderHadith(view, p[0]) },
  names: { tab: 'home', fn: (p) => renderNames(view, p[0]) },
  tracker: { tab: 'home', fn: (p) => (p[0] === 'khatm' ? renderKhatm(view) : renderTracker(view)) },
  qibla: { tab: 'home', fn: () => renderQibla(view) },
  schedule: { tab: 'home', fn: () => renderSchedule(view) },
  settings: { tab: 'settings', fn: () => renderSettings(view) },
};

async function route() {
  const my = ++seq;
  closeSheet();
  cleanup?.(); cleanup = null;
  const parts = location.hash.replace(/^#\/?/, '').split('/').filter(Boolean);
  const r = ROUTES[parts[0] || ''] || ROUTES[''];
  const name = ROUTES[parts[0] || ''] ? (parts[0] || 'home') : 'home';
  paintTabs(r.tab);
  view.style.animation = 'none'; void view.offsetWidth; view.style.animation = '';
  const keepScroll = parts[0] === 'quran' && parts[2];
  if (!keepScroll) window.scrollTo(0, 0);
  document.title = (TITLES[name] || 'Свет') + (name === 'home' ? '' : ' · Свет');
  let c;
  try { c = await r.fn(parts.slice(1)); } catch (e) {
    console.error(e);
    view.innerHTML = '<div class="empty" style="margin-top:80px"><h3>Что-то пошло не так</h3><p>Попробуйте обновить страницу.</p><a class="btn" href="#/" style="margin-top:14px">На главную</a></div>';
  }
  if (my !== seq) { c?.(); return; }
  cleanup = c || null;
}
addEventListener('hashchange', route);

/* ───── Мини-плеер ───── */
function paintPlayer(a) {
  const el = $('#miniplayer');
  if (!el) return;
  if (!a.surah) { el.hidden = true; document.body.classList.remove('has-player'); return; }
  el.hidden = false; document.body.classList.add('has-player');
  const name = surahNames[a.surah - 1] || `Сура ${a.surah}`;
  el.innerHTML = `<button class="mp-main" id="mp-toggle" aria-label="${a.playing ? 'Пауза' : 'Играть'}">${icon(a.loading && !a.playing ? 'timer' : a.playing ? 'pause' : 'play')}</button>
    <a class="mp-text" href="#/quran/${a.surah}/${a.ayah}"><b>${esc(name)}</b><small>Аят ${a.ayah}${a.repeatTotal > 1 ? ` · повтор ${a.repeatTotal - a.repeatLeft + 1}/${a.repeatTotal}` : ''}${a.sleepAt ? ' · таймер сна' : ''}</small></a>
    <button class="icon-btn" id="mp-sleep" aria-label="Таймер сна" aria-pressed="${!!a.sleepAt}">${icon('moon')}</button>
    <button class="icon-btn" id="mp-stop" aria-label="Остановить">${icon('stop')}</button>`;
}
$('#miniplayer').addEventListener('click', (e) => {
  if (e.target.closest('#mp-toggle')) return togglePlay();
  if (e.target.closest('#mp-stop')) return stopAudio();
  if (e.target.closest('#mp-sleep')) {
    openSheet('Таймер сна', `<div class="act-list">${[15, 30, 45, 60, 90].map((m) => `<button data-m="${m}"><span>${m} минут</span></button>`).join('')}
      <button data-m="0"><span>Отключить таймер</span></button></div>`, (root, close) => {
      root.addEventListener('click', (ev) => {
        const b = ev.target.closest('[data-m]');
        if (!b) return;
        const m = +b.dataset.m;
        setSleepTimer(m);
        toast(m ? `Воспроизведение остановится через ${m} минут` : 'Таймер сна отключён');
        close();
      });
    }, { done: false });
  }
});
onAudio(paintPlayer);

/* ───── Запуск ───── */
paintTabs('home');
route();
getQuran().then((surahs) => {
  setAyahCounts(surahs.map((s) => s.ayahs.length));
  surahNames = surahs.map((s) => s.ru);
  paintPlayer(getAudio());
}).catch(() => { /* экраны сами покажут ошибку загрузки */ });

if ('serviceWorker' in navigator && location.protocol.startsWith('http') && !window.__SVET_DATA__) {
  addEventListener('load', () => navigator.serviceWorker.register('/sw.js').catch(() => {}));
}

/* Единый файл (GitHub Pages): убираем service worker и кэш старой Flutter-версии, иначе браузер покажет прежний сайт */
if (window.__SVET_DATA__) {
  try {
    navigator.serviceWorker?.getRegistrations().then((rs) => rs.forEach((r) => r.unregister())).catch(() => {});
    window.caches?.keys().then((ks) => ks.forEach((k) => caches.delete(k))).catch(() => {});
  } catch { /* без доступа к service worker */ }
}

})();
</script>
</body>
</html>
